inline constexpr uint64_t INF_TXID     = UINT64_MAX;
inline constexpr uint64_t ABORT_TXID   = UINT64_MAX - 1;
inline constexpr size_t   CACHELINE_SZ = 64;
inline constexpr size_t   MAX_THREADS  = 128;
inline constexpr size_t   BLOCK_SZ     = 4096;
inline constexpr size_t   LOG_RING_CAP = 1024 * 1024 * 64; // 64 MB Direct WAL
inline constexpr uint32_t WAL_MAGIC    = 0x3043564Du;   // "MVC0"

// Fast CRC32C implementation using SSE4.2 / intrinsics fallback
inline uint32_t compute_crc32c(uint32_t crc, const uint8_t* buf, size_t len) noexcept {
    crc = ~crc;
    size_t i = 0;
#if defined(__SSE4_2__) || defined(__x86_64__)
    while (i + 8 <= len) {
        uint64_t val;
        std::memcpy(&val, buf + i, 8);
        crc = static_cast<uint32_t>(__builtin_ia32_crc32di(crc, val));
        i += 8;
    }
    while (i + 4 <= len) {
        uint32_t val;
        std::memcpy(&val, buf + i, 4);
        crc = __builtin_ia32_crc32si(crc, val);
        i += 4;
    }
#endif
    while (i < len) {
        crc = __builtin_ia32_crc32qi(crc, buf[i]);
        i++;
    }
    return ~crc;
}

// ============================================================================
// COMPONENT 1: EPOCH-BASED RECLAMATION (EBR)
// ============================================================================
class EpochManager {
public:
    struct alignas(CACHELINE_SZ) ThreadState {
        std::atomic<bool>     is_active{false};
        std::atomic<uint64_t> local_epoch{0};
        std::atomic<bool>     registered{false};
    };

    struct alignas(CACHELINE_SZ) RetiredNode {
        void* ptr{nullptr};
        void (*deleter)(void*){nullptr};
        RetiredNode* next{nullptr};
    };

    struct ThreadLimboList {
        std::array<RetiredNode*, 3> buckets{nullptr, nullptr, nullptr};
        size_t pending_count{0};
    };

    static EpochManager& instance() {
        static EpochManager mgr;
        return mgr;
    }

    uint64_t get_global_epoch() const noexcept {
        return global_epoch_.load(std::memory_order_relaxed);
    }

    size_t register_thread() {
        for (size_t i = 0; i < MAX_THREADS; ++i) {
            bool expected = false;
            if (threads_[i].registered.compare_exchange_strong(expected, true, std::memory_order_acq_rel)) {
                return i;
            }
        }
        throw std::runtime_error("Exceeded maximum thread capacity for EBR");
    }

    void unregister_thread(size_t tid) {
        assert(tid < MAX_THREADS);
        threads_[tid].is_active.store(false, std::memory_order_release);
        threads_[tid].registered.store(false, std::memory_order_release);
    }

    void enter_critical(size_t tid) noexcept {
        threads_[tid].local_epoch.store(global_epoch_.load(std::memory_order_relaxed), std::memory_order_relaxed);
        threads_[tid].is_active.store(true, std::memory_order_seq_cst);
    }

    void exit_critical(size_t tid) noexcept {
        threads_[tid].is_active.store(false, std::memory_order_seq_cst);
    }

    template <typename T>
    void retire(size_t tid, T* ptr) {
        if (!ptr) return;
        auto* node = new RetiredNode();
        node->ptr = ptr;
        node->deleter = [](void* p) { delete static_cast<T*>(p); };

        uint64_t ge = global_epoch_.load(std::memory_order_relaxed);
        size_t b_idx = ge % 3;

        auto& limbo = tls_limbo_;
        node->next = limbo.buckets[b_idx];
        limbo.buckets[b_idx] = node;
        limbo.pending_count++;

        if (limbo.pending_count >= 64) {
            try_advance_and_reclaim(tid);
        }
    }

    void try_advance_and_reclaim(size_t tid) {
        uint64_t ge = global_epoch_.load(std::memory_order_relaxed);

        // Check if all active threads are at the current global epoch
        for (size_t i = 0; i < MAX_THREADS; ++i) {
            if (threads_[i].registered.load(std::memory_order_acquire)) {
                if (threads_[i].is_active.load(std::memory_order_seq_cst)) {
                    if (threads_[i].local_epoch.load(std::memory_order_relaxed) < ge) {
                        return; // Cannot advance; a reader is in an older epoch
                    }
                }
            }
        }

        // Advance global epoch
        if (global_epoch_.compare_exchange_strong(ge, ge + 1, std::memory_order_acq_rel)) {
            // Safe to reclaim (ge - 2) which is (ge + 1) % 3
            size_t safe_bucket = (ge + 1) % 3;
            reclaim_bucket(tls_limbo_.buckets[safe_bucket]);
            tls_limbo_.buckets[safe_bucket] = nullptr;
        }
    }

private:
    EpochManager() : global_epoch_(1) {}
    ~EpochManager() {
        for (size_t i = 0; i < 3; ++i) {
            reclaim_bucket(tls_limbo_.buckets[i]);
        }
    }

    static void reclaim_bucket(RetiredNode* head) {
        while (head) {
            RetiredNode* nxt = head->next;
            if (head->deleter && head->ptr) {
                head->deleter(head->ptr);
            }
            delete head;
            head = nxt;
        }
    }

    alignas(CACHELINE_SZ) std::atomic<uint64_t> global_epoch_;
    std::array<ThreadState, MAX_THREADS> threads_;
    inline static thread_local ThreadLimboList tls_limbo_;
};

// RAII Epoch Guard
struct EpochGuard {
    size_t tid;
    explicit EpochGuard(size_t thread_id) : tid(thread_id) {
        EpochManager::instance().enter_critical(tid);
    }
    ~EpochGuard() {
        EpochManager::instance().exit_critical(tid);
    }
    EpochGuard(const EpochGuard&) = delete;
    EpochGuard& operator=(const EpochGuard&) = delete;
};

// ============================================================================
// COMPONENT 2: MVCC DATA TYPES & LOCK-FREE VERSION INDEX
// ============================================================================
enum class RecordType : uint32_t {
    PUT = 1,
    DELETE = 2
};

struct VersionRecord {
    std::atomic<uint64_t> tx_id_created{INF_TXID};
    std::atomic<uint64_t> tx_id_expired{INF_TXID};
    std::atomic<VersionRecord*> prev{nullptr};
    uint32_t data_len{0};
    RecordType type{RecordType::PUT};
    alignas(8) uint8_t payload[0]; // Flexible array member

    static VersionRecord* create(uint64_t tx_created, RecordType type, std::span<const uint8_t> data) {
        size_t total_sz = sizeof(VersionRecord) + data.size();
        auto* mem = ::operator new(total_sz);
        auto* rec = new (mem) VersionRecord();
        rec->tx_id_created.store(tx_created, std::memory_order_relaxed);
        rec->tx_id_expired.store(INF_TXID, std::memory_order_relaxed);
        rec->prev.store(nullptr, std::memory_order_relaxed);
        rec->data_len = static_cast<uint32_t>(data.size());
        rec->type = type;
        if (!data.empty()) {
            std::memcpy(rec->payload, data.data(), data.size());
        }
        return rec;
    }

    static void destroy(VersionRecord* rec) {
        if (!rec) return;
        rec->~VersionRecord();
        ::operator delete(rec);
    }
};

// Lock-Free Concurrent Index using an Atomic Fixed Array / SkipList Model
class LockFreeMVCCIndex {
public:
    static constexpr size_t INDEX_CAPACITY = 1048576; // 1M direct slots for benchmark demo

    struct Slot {
        std::atomic<uint64_t> key{0};
        std::atomic<VersionRecord*> head{nullptr};
        std::atomic<bool> occupied{false};
    };

    LockFreeMVCCIndex() : table_(new Slot[INDEX_CAPACITY]) {}

    ~LockFreeMVCCIndex() {
        for (size_t i = 0; i < INDEX_CAPACITY; ++i) {
            if (table_[i].occupied.load(std::memory_order_relaxed)) {
                VersionRecord* curr = table_[i].head.load(std::memory_order_relaxed);
                while (curr) {
                    VersionRecord* nxt = curr->prev.load(std::memory_order_relaxed);
                    VersionRecord::destroy(curr);
                    curr = nxt;
                }
            }
        }
        delete[] table_;
    }

    std::atomic<VersionRecord*>* get_or_create_head(uint64_t key) {
        size_t idx = hash(key) % INDEX_CAPACITY;
        for (size_t probe = 0; probe < 256; ++probe) {
            size_t slot_idx = (idx + probe) % INDEX_CAPACITY;
            Slot& slot = table_[slot_idx];

            if (!slot.occupied.load(std::memory_order_acquire)) {
                bool expected = false;
                if (slot.occupied.compare_exchange_strong(expected, true, std::memory_order_acq_rel)) {
                    slot.key.store(key, std::memory_order_release);
                    return &slot.head;
                }
            }
            if (slot.key.load(std::memory_order_acquire) == key) {
                return &slot.head;
            }
        }
        throw std::runtime_error("Hash table capacity/probe limit exceeded");
    }

    std::atomic<VersionRecord*>* find_head(uint64_t key) const noexcept {
        size_t idx = hash(key) % INDEX_CAPACITY;
        for (size_t probe = 0; probe < 256; ++probe) {
            size_t slot_idx = (idx + probe) % INDEX_CAPACITY;
            const Slot& slot = table_[slot_idx];
            if (!slot.occupied.load(std::memory_order_acquire)) {
                return nullptr;
            }
            if (slot.key.load(std::memory_order_acquire) == key) {
                return const_cast<std::atomic<VersionRecord*>*>(&slot.head);
            }
        }
        return nullptr;
    }

private:
    static uint64_t hash(uint64_t x) noexcept {
        x = (x ^ (x >> 30)) * UINT64_C(0xbf58476d1ce4e5b9);
        x = (x ^ (x >> 27)) * UINT64_C(0x94d049bb133111eb);
        x = x ^ (x >> 31);
        return x;
    }

    Slot* table_;
};

// ============================================================================
// COMPONENT 3: ZERO-COPY DIRECT I/O WAL VIA LINUX io_uring
// ============================================================================
#pragma pack(push, 1)
struct WalLogEntryHeader {
    uint32_t magic;
    uint32_t crc32;
    uint64_t lsn;
    uint64_t tx_id;
    uint64_t key;
    uint32_t payload_len;
    RecordType type;
};
#pragma pack(pop)

class IoUringWal {
public:
    explicit IoUringWal(const std::string& path) : running_(true) {
        fd_ = ::open(path.c_str(), O_DIRECT | O_RDWR | O_CREAT | O_TRUNC, 0644);
        if (fd_ < 0) {
            throw std::runtime_error("Failed to open WAL file with O_DIRECT: " + std::string(strerror(errno)));
        }

        // Allocate 4096-byte aligned circular log buffer
        void* mem = nullptr;
        if (::posix_memalign(&mem, BLOCK_SZ, LOG_RING_CAP) != 0) {
            throw std::runtime_error("Failed to allocate aligned WAL buffer");
        }
        ring_buffer_ = static_cast<uint8_t*>(mem);

        // Setup io_uring with SQPOLL
        struct io_uring_params params;
        std::memset(&params, 0, sizeof(params));
        params.flags = IORING_SETUP_SQPOLL;
        params.sq_thread_idle = 2000; // 2ms idle before sleeping

        if (io_uring_queue_init_params(256, &ring_, &params) < 0) {
            // Fallback without SQPOLL if kernel unprivileged
            if (io_uring_queue_init(256, &ring_, 0) < 0) {
                throw std::runtime_error("Failed to initialize io_uring");
            }
        }

        // Register fixed Direct I/O buffer
        struct iovec iov;
        iov.iov_base = ring_buffer_;
        iov.iov_len = LOG_RING_CAP;
        io_uring_register_buffers(&ring_, &iov, 1);

        flusher_thread_ = std::thread(&IoUringWal::flusher_loop, this);
    }

    ~IoUringWal() {
        running_.store(false, std::memory_order_release);
        if (flusher_thread_.joinable()) {
            flusher_thread_.join();
        }
        io_uring_unregister_buffers(&ring_);
        io_uring_queue_exit(&ring_);
        ::free(ring_buffer_);
        ::close(fd_);
    }

    // Lock-free tail reservation
    std::pair<uint64_t, uint64_t> reserve_log_space(size_t total_len) {
        uint64_t lsn = next_lsn_.fetch_add(total_len, std::memory_order_acq_rel);
        return {lsn, lsn % LOG_RING_CAP};
    }

    std::future<void> write_entry(uint64_t tx_id, uint64_t key, RecordType type, std::span<const uint8_t> payload) {
        size_t total_len = sizeof(WalLogEntryHeader) + payload.size();
        auto [lsn, ring_offset] = reserve_log_space(total_len);

        WalLogEntryHeader hdr;
        hdr.magic = WAL_MAGIC;
        hdr.lsn = lsn;
        hdr.tx_id = tx_id;
        hdr.key = key;
        hdr.type = type;
        hdr.payload_len = static_cast<uint32_t>(payload.size());
        hdr.crc32 = compute_crc32c(0, payload.data(), payload.size());
        hdr.crc32 = compute_crc32c(hdr.crc32, reinterpret_cast<const uint8_t*>(&hdr) + 8, sizeof(WalLogEntryHeader) - 8);

        // Copy directly into ring buffer
        if (ring_offset + total_len <= LOG_RING_CAP) {
            std::memcpy(ring_buffer_ + ring_offset, &hdr, sizeof(WalLogEntryHeader));
            if (!payload.empty()) {
                std::memcpy(ring_buffer_ + ring_offset + sizeof(WalLogEntryHeader), payload.data(), payload.size());
            }
        } else {
            // Handle ring-wrap
            size_t first_part = LOG_RING_CAP - ring_offset;
            if (first_part >= sizeof(WalLogEntryHeader)) {
                std::memcpy(ring_buffer_ + ring_offset, &hdr, sizeof(WalLogEntryHeader));
                size_t p1 = first_part - sizeof(WalLogEntryHeader);
                if (p1 > 0) std::memcpy(ring_buffer_ + ring_offset + sizeof(WalLogEntryHeader), payload.data(), p1);
                std::memcpy(ring_buffer_, payload.data() + p1, payload.size() - p1);
            } else {
                std::memcpy(ring_buffer_ + ring_offset, &hdr, first_part);
                std::memcpy(ring_buffer_, reinterpret_cast<uint8_t*>(&hdr) + first_part, sizeof(WalLogEntryHeader) - first_part);
                std::memcpy(ring_buffer_ + (sizeof(WalLogEntryHeader) - first_part), payload.data(), payload.size());
            }
        }

        auto commit_promise = std::make_shared<std::promise<void>>();
        std::future<void> fut = commit_promise->get_future();

        {
            std::lock_guard<std::mutex> lock(promise_mtx_);
            pending_promises_.push_back({lsn + total_len, commit_promise});
        }

        ready_lsn_.store(lsn + total_len, std::memory_order_release);
        return fut;
    }

private:
    struct PendingCommit {
        uint64_t target_lsn;
        std::shared_ptr<std::promise<void>> promise;
    };

    void flusher_loop() {
        uint64_t flushed_lsn = 0;
        uint64_t file_offset = 0;

        while (running_.load(std::memory_order_acquire) || (ready_lsn_.load(std::memory_order_acquire) > flushed_lsn)) {
            uint64_t cur_ready = ready_lsn_.load(std::memory_order_acquire);
            if (cur_ready <= flushed_lsn) {
                std::this_thread::yield();
                continue;
            }

            size_t bytes_to_flush = cur_ready - flushed_lsn;
            size_t aligned_bytes = (bytes_to_flush + BLOCK_SZ - 1) & ~(BLOCK_SZ - 1);

            size_t ring_offset = flushed_lsn % LOG_RING_CAP;
            if (ring_offset + aligned_bytes > LOG_RING_CAP) {
                aligned_bytes = LOG_RING_CAP - ring_offset;
            }

            struct io_uring_sqe* sqe = io_uring_get_sqe(&ring_);
            while (!sqe) {
                io_uring_submit(&ring_);
                sqe = io_uring_get_sqe(&ring_);
            }

            io_uring_prep_write_fixed(sqe, fd_, ring_buffer_ + ring_offset, aligned_bytes, file_offset, 0);
            sqe->user_data = flushed_lsn + aligned_bytes;
            io_uring_submit(&ring_);

            struct io_uring_cqe* cqe = nullptr;
            int ret = io_uring_wait_cqe(&ring_, &cqe);
            if (ret >= 0 && cqe) {
                if (cqe->res >= 0) {
                    flushed_lsn = cqe->user_data;
                    file_offset += cqe->res;
                    persisted_lsn_.store(flushed_lsn, std::memory_order_release);
                    fulfill_promises(flushed_lsn);
                }
                io_uring_cqe_seen(&ring_, cqe);
            }
        }
    }

    void fulfill_promises(uint64_t persisted_lsn) {
        std::vector<PendingCommit> ready;
        {
            std::lock_guard<std::mutex> lock(promise_mtx_);
            auto it = pending_promises_.begin();
            while (it != pending_promises_.end()) {
                if (it->target_lsn <= persisted_lsn) {
                    ready.push_back(std::move(*it));
                    it = pending_promises_.erase(it);
                } else {
                    ++it;
                }
            }
        }
        for (auto& pc : ready) {
            pc.promise->set_value();
        }
    }

    int fd_{-1};
    struct io_uring ring_;
    uint8_t* ring_buffer_{nullptr};
    std::atomic<bool> running_{false};
    std::thread flusher_thread_;

    alignas(CACHELINE_SZ) std::atomic<uint64_t> next_lsn_{0};
    alignas(CACHELINE_SZ) std::atomic<uint64_t> ready_lsn_{0};
    alignas(CACHELINE_SZ) std::atomic<uint64_t> persisted_lsn_{0};

    std::mutex promise_mtx_;
    std::vector<PendingCommit> pending_promises_;
};

// ============================================================================
// COMPONENT 4: TRANSACTION CONTEXT & MVCC ENGINE (SI / FIRST-COMMITTER-WINS)
// ============================================================================
class TransactionEngine {
public:
    struct WriteIntent {
        uint64_t key;
        RecordType type;
        std::vector<uint8_t> value;
        VersionRecord* installed_version{nullptr};
        VersionRecord* previous_visible_version{nullptr};
    };

    class Transaction {
    public:
        Transaction(TransactionEngine& engine, size_t tid)
            : engine_(engine), tid_(tid), is_active_(true) {
            EpochManager::instance().enter_critical(tid_);
            tx_id_ = engine_.alloc_tx_id();
            read_ts_ = tx_id_;
        }

        ~Transaction() {
            if (is_active_) {
                abort();
            }
            EpochManager::instance().exit_critical(tid_);
        }

        uint64_t tx_id() const noexcept { return tx_id_; }

        std::optional<std::vector<uint8_t>> get(uint64_t key) {
            // Check uncommitted write-set first
            for (auto it = write_set_.rbegin(); it != write_set_.rend(); ++it) {
                if (it->key == key) {
                    if (it->type == RecordType::DELETE) return std::nullopt;
                    return it->value;
                }
            }

            auto* head_ptr = engine_.index_.find_head(key);
            if (!head_ptr) return std::nullopt;

            VersionRecord* curr = head_ptr->load(std::memory_order_acquire);
            while (curr) {
                uint64_t c = curr->tx_id_created.load(std::memory_order_acquire);
                uint64_t e = curr->tx_id_expired.load(std::memory_order_acquire);

                // Visibility predicate for Snapshot Isolation
                if (c <= read_ts_ && (e > read_ts_ || e == tx_id_)) {
                    if (curr->type == RecordType::DELETE) {
                        return std::nullopt;
                    }
                    return std::vector<uint8_t>(curr->payload, curr->payload + curr->data_len);
                }
                curr = curr->prev.load(std::memory_order_acquire);
            }
            return std::nullopt;
        }

        bool put(uint64_t key, std::span<const uint8_t> val) {
            return stage_write(key, RecordType::PUT, val);
        }

        bool remove(uint64_t key) {
            return stage_write(key, RecordType::DELETE, {});
        }

        bool commit() {
            if (!is_active_) return false;
            if (write_set_.empty()) {
                is_active_ = false;
                return true;
            }

            // Group Commit WAL Logging
            std::vector<std::future<void>> futures;
            futures.reserve(write_set_.size());
            for (const auto& w : write_set_) {
                futures.push_back(engine_.wal_.write_entry(tx_id_, w.key, w.type, w.value));
            }

            // Await kernel Direct I/O completion
            for (auto& fut : futures) {
                fut.get();
            }

            uint64_t commit_ts = engine_.alloc_tx_id();

            // Finalize visibility handoff
            for (auto& w : write_set_) {
                w.installed_version->tx_id_created.store(commit_ts, std::memory_order_release);
                if (w.previous_visible_version) {
                    w.previous_visible_version->tx_id_expired.store(commit_ts, std::memory_order_release);
                    // Schedule previous version for EBR reclamation
                    EpochManager::instance().retire(tid_, w.previous_visible_version);
                }
            }

            write_set_.clear();
            is_active_ = false;
            return true;
        }

        void abort() {
            if (!is_active_) return;
            for (auto& w : write_set_) {
                if (w.installed_version) {
                    // Mark as tombstone aborted
                    w.installed_version->tx_id_created.store(ABORT_TXID, std::memory_order_release);
                    w.installed_version->tx_id_expired.store(ABORT_TXID, std::memory_order_release);

                    if (w.previous_visible_version) {
                        w.previous_visible_version->tx_id_expired.store(INF_TXID, std::memory_order_release);
                    }

                    // Unlink uncommitted version from head
                    auto* head_ptr = engine_.index_.find_head(w.key);
                    if (head_ptr) {
                        VersionRecord* expected = w.installed_version;
                        VersionRecord* old_next = w.installed_version->prev.load(std::memory_order_relaxed);
                        head_ptr->compare_exchange_strong(expected, old_next, std::memory_order_acq_rel);
                    }
                    EpochManager::instance().retire(tid_, w.installed_version);
                }
            }
            write_set_.clear();
            is_active_ = false;
        }

    private:
        bool stage_write(uint64_t key, RecordType type, std::span<const uint8_t> val) {
            auto* head_ptr = engine_.index_.get_or_create_head(key);
            VersionRecord* cur_head = head_ptr->load(std::memory_order_acquire);
            VersionRecord* visible_v = nullptr;

            // Step 1: Detect write conflicts (First-Committer-Wins)
            VersionRecord* trav = cur_head;
            while (trav) {
                uint64_t c = trav->tx_id_created.load(std::memory_order_acquire);
                uint64_t e = trav->tx_id_expired.load(std::memory_order_acquire);

                if (c > read_ts_ && c != tx_id_) {
                    return false; // Concurrent active transaction committed a newer version
                }
                if (c <= read_ts_ && (e > read_ts_ || e == tx_id_)) {
                    visible_v = trav;
                    break;
                }
                trav = trav->prev.load(std::memory_order_acquire);
            }

            // Step 2: Atomic CAS update claiming the update slot on visible version
            if (visible_v) {
                uint64_t expected_exp = INF_TXID;
                if (!visible_v->tx_id_expired.compare_exchange_strong(expected_exp, tx_id_, std::memory_order_acq_rel)) {
                    return false; // Conflict: lost race to another transaction
                }
            }

            // Step 3: Instantiate new uncommitted version record
            auto* new_rec = VersionRecord::create(tx_id_, type, val);

            // Step 4: Lock-free prepend onto version chain
            do {
                cur_head = head_ptr->load(std::memory_order_acquire);
                new_rec->prev.store(cur_head, std::memory_order_relaxed);
            } while (!head_ptr->compare_exchange_weak(cur_head, new_rec, std::memory_order_release, std::memory_order_acquire));

            std::vector<uint8_t> val_vec(val.begin(), val.end());
            write_set_.push_back(WriteIntent{key, type, std::move(val_vec), new_rec, visible_v});
            return true;
        }

        TransactionEngine& engine_;
        size_t tid_;
        uint64_t tx_id_;
        uint64_t read_ts_;
        bool is_active_{false};
        std::vector<WriteIntent> write_set_;
    };

    explicit TransactionEngine(const std::string& wal_path)
        : wal_(wal_path), global_tx_id_(100) {}

    Transaction begin_transaction(size_t tid) {
        return Transaction(*this, tid);
    }

    uint64_t alloc_tx_id() noexcept {
        return global_tx_id_.fetch_add(1, std::memory_order_acq_rel);
    }

    LockFreeMVCCIndex index_;
    IoUringWal wal_;

private:
    alignas(CACHELINE_SZ) std::atomic<uint64_t> global_tx_id_;
};

// ============================================================================
// COMPONENT 5: CRASH RECOVERY ENGINE (WAL REPLAY)
// ============================================================================
class RecoveryManager {
public:
    static void recover_from_wal(const std::string& wal_path, LockFreeMVCCIndex& index, uint64_t& max_txid) {
        int fd = ::open(wal_path.c_str(), O_RDONLY | O_DIRECT);
        if (fd < 0) {
            fd = ::open(wal_path.c_str(), O_RDONLY); // Fallback if O_DIRECT not permitted
            if (fd < 0) return; // Fresh database
        }

        struct stat st;
        if (::fstat(fd, &st) < 0 || st.st_size == 0) {
            ::close(fd);
            return;
        }

        size_t aligned_sz = (st.st_size + BLOCK_SZ - 1) & ~(BLOCK_SZ - 1);
        void* buf = nullptr;
        if (::posix_memalign(&buf, BLOCK_SZ, aligned_sz) != 0) {
            ::close(fd);
            throw std::runtime_error("Recovery buffer allocation failed");
        }

        ssize_t bytes_read = ::pread(fd, buf, aligned_sz, 0);
        ::close(fd);
        if (bytes_read <= 0) {
            ::free(buf);
            return;
        }

        const uint8_t* ptr = static_cast<const uint8_t*>(buf);
        size_t offset = 0;
        max_txid = 0;

        while (offset + sizeof(WalLogEntryHeader) <= static_cast<size_t>(bytes_read)) {
            const auto* hdr = reinterpret_cast<const WalLogEntryHeader*>(ptr + offset);
            if (hdr->magic != WAL_MAGIC) {
                break; // Torn write / zero padding boundary reached
            }

            size_t entry_total_sz = sizeof(WalLogEntryHeader) + hdr->payload_len;
            if (offset + entry_total_sz > static_cast<size_t>(bytes_read)) {
                break; // Partial tail write
            }

            const uint8_t* payload_ptr = ptr + offset + sizeof(WalLogEntryHeader);
            uint32_t expected_crc = compute_crc32c(0, payload_ptr, hdr->payload_len);
            expected_crc = compute_crc32c(expected_crc, reinterpret_cast<const uint8_t*>(hdr) + 8, sizeof(WalLogEntryHeader) - 8);

            if (hdr->crc32 != expected_crc) {
                break; // Corrupted record found, stop recovery at valid prefix
            }

            // Install recovered version into MVCC chain
            std::span<const uint8_t> payload_span(payload_ptr, hdr->payload_len);
            auto* rec = VersionRecord::create(hdr->tx_id, hdr->type, payload_span);
            rec->tx_id_expired.store(INF_TXID, std::memory_order_relaxed);

            auto* head_ptr = index.get_or_create_head(hdr->key);
            VersionRecord* cur_head = head_ptr->load(std::memory_order_relaxed);
            if (cur_head) {
                cur_head->tx_id_expired.store(hdr->tx_id, std::memory_order_relaxed);
            }
            rec->prev.store(cur_head, std::memory_order_relaxed);
            head_ptr->store(rec, std::memory_order_relaxed);

            if (hdr->tx_id > max_txid) max_txid = hdr->tx_id;
            offset += entry_total_sz;
        }

        ::free(buf);
    }
};

