void run_stress_benchmark() {
    std::cout << "==============================================================\n";
    std::cout << "Starting High-Throughput MVCC & io_uring WAL Stress Benchmark\n";
    std::cout << "==============================================================\n";

    TransactionalEngine engine("/tmp/mvcc_bench.wal");

    constexpr size_t NUM_WRITERS = 4;
    constexpr size_t NUM_READERS = 4;
    constexpr size_t NUM_SCANNERS = 2;
    constexpr size_t OPS_PER_THREAD = 10'000;

    std::atomic<bool> start_flag{false};
    std::atomic<uint64_t> total_writes{0};
    std::atomic<uint64_t> total_reads{0};
    std::atomic<uint64_t> total_scans{0};

    auto writer_worker = [&](size_t worker_id) {
        size_t tid = EpochManager::instance().register_thread();
        while (!start_flag.load(std::memory_order_acquire)) {}

        for (size_t i = 0; i < OPS_PER_THREAD; ++i) {
            TxID tx = engine.begin_transaction();
            uint64_t key = (worker_id * OPS_PER_THREAD + i) % 1000;
            std::string val = "val_" + std::to_string(tx);

            bool ok = engine.write(tx, key, val, tid);
            assert(ok);
            total_writes.fetch_add(1, std::memory_order_relaxed);
        }

        EpochManager::instance().deregister_thread(tid);
    };

    auto reader_worker = [&](size_t) {
        size_t tid = EpochManager::instance().register_thread();
        while (!start_flag.load(std::memory_order_acquire)) {}

        for (size_t i = 0; i < OPS_PER_THREAD; ++i) {
            TxID snapshot_ts = engine.begin_transaction();
            uint64_t key = rand() % 1000;

            auto res = engine.read(key, snapshot_ts, tid);
            if (res.has_value()) {
                assert(res->rfind("val_", 0) == 0); // Snapshot integrity check
            }
            total_reads.fetch_add(1, std::memory_order_relaxed);
        }

        EpochManager::instance().deregister_thread(tid);
    };

    auto scanner_worker = [&](size_t) {
        size_t tid = EpochManager::instance().register_thread();
        while (!start_flag.load(std::memory_order_acquire)) {}

        for (size_t i = 0; i < (OPS_PER_THREAD / 10); ++i) {
