constexpr size_t MAX_THREADS            = 128;
constexpr size_t MAX_KEYS_PER_LEAF      = 16;
constexpr size_t SLAB_CAPACITY_PER_EPOCH= 8192;
constexpr uint64_t EPOCH_INACTIVE       = UINT64_MAX;

using KeyType       = uint64_t;
using ValueType     = uint64_t;
using TxnTimestamp  = uint64_t;
using TxnId         = uint64_t;

// ============================================================================
// Transaction Status Table (Snapshot Isolation / MVCC Support)
// ============================================================================
enum class TxnState : uint8_t {
    ACTIVE    = 0,
    COMMITTED = 1,
    ABORTED   = 2
};

struct alignas(hardware_destructive_interference_size) TxnDescriptor {
    std::atomic<TxnState> state{TxnState::ACTIVE};
    std::atomic<TxnTimestamp> commit_ts{0};
};

class TxnManager {
public:
    static constexpr size_t MAX_TXNS = 1048576;
    static TxnManager& instance() {
        static TxnManager mgr;
        return mgr;
    }

    TxnDescriptor& get_desc(TxnId tx_id) {
        return descriptors_[tx_id % MAX_TXNS];
    }

private:
    TxnManager() = default;
    std::array<TxnDescriptor, MAX_TXNS> descriptors_;
};

// ============================================================================
// Node Type Definitions & Cache-Line Aligned Memory Structures
// ============================================================================
enum class NodeType : uint8_t {
    CONSOLIDATED_LEAF,
    RECORD_DELTA,
    SPLIT_DELTA,
    ABORT_DELTA
};

struct alignas(hardware_destructive_interference_size) Node {
    NodeType type;
    Node* next{nullptr}; // Points to older delta or base node

    explicit Node(NodeType t, Node* n = nullptr) : type(t), next(n) {}
    virtual ~Node() = default;
};

// Delta record for inserts/updates
struct alignas(hardware_destructive_interference_size) RecordDelta : public Node {
    KeyType        key;
    ValueType      value;
    TxnId          tx_id;
    TxnTimestamp   creation_ts;

    RecordDelta(KeyType k, ValueType v, TxnId tx, TxnTimestamp ts, Node* pred)
        : Node(NodeType::RECORD_DELTA, pred),
          key(k), value(v), tx_id(tx), creation_ts(ts) {}
};

// Split delta inserted during node splits
struct alignas(hardware_destructive_interference_size) SplitDelta : public Node {
    KeyType split_key;
    Node*   right_child;

    SplitDelta(KeyType sk, Node* r_child, Node* pred)
        : Node(NodeType::SPLIT_DELTA, pred),
          split_key(sk), right_child(r_child) {}
};

// Delta explicitly invalidating an aborted transaction's update
struct alignas(hardware_destructive_interference_size) AbortDelta : public Node {
    KeyType key;
    TxnId   aborted_tx_id;

    AbortDelta(KeyType k, TxnId tx, Node* pred)
        : Node(NodeType::ABORT_DELTA, pred),
          key(k), aborted_tx_id(tx) {}
};

// Key-Value Slot for Base Consolidated Leaf
struct KVPair {
    KeyType      key;
    ValueType    value;
    TxnTimestamp commit_ts;
};

// Consolidated Base Leaf Node
struct alignas(hardware_destructive_interference_size) ConsolidatedLeafNode : public Node {
    uint32_t count{0};
    KeyType  low_key{0};
    KeyType  high_key{UINT64_MAX};
    std::array<KVPair, MAX_KEYS_PER_LEAF> slots;

    ConsolidatedLeafNode() : Node(NodeType::CONSOLIDATED_LEAF, nullptr) {}
};

// ============================================================================
// Thread-Safe NUMA-Aware Epoch Manager (Bounded-Latency EBR)
// ============================================================================
class EpochManager {
public:
    static EpochManager& instance() {
        static EpochManager mgr;
        return mgr;
    }

    uint64_t get_global_epoch() const noexcept {
        return global_epoch_.load(std::memory_order_acquire);
    }

    uint32_t register_thread() {
        uint32_t id = thread_counter_.fetch_add(1, std::memory_order_relaxed);
        if (id >= MAX_THREADS) {
            std::terminate(); // Maximum thread capacity exceeded
        }
        return id;
    }

    // Enter critical section: synchronize with current epoch
    void enter(uint32_t thread_id) noexcept {
        uint64_t g_epoch = global_epoch_.load(std::memory_order_relaxed);
        // Store with Release/Acquire semantic ensuring subsequent pointer loads observe updated state
        thread_epochs_[thread_id].epoch.store(g_epoch, std::memory_order_release);
        std::atomic_thread_fence(std::memory_order_seq_cst);
    }

    // Quiescent point / Exit critical section
    void exit(uint32_t thread_id) noexcept {
        thread_epochs_[thread_id].epoch.store(EPOCH_INACTIVE, std::memory_order_release);
    }

    // Try to advance global epoch if all registered active threads observed older epochs
    void try_advance_epoch() {
        uint64_t current_epoch = global_epoch_.load(std::memory_order_relaxed);
        for (size_t i = 0; i < thread_counter_.load(std::memory_order_relaxed); ++i) {
            uint64_t t_epoch = thread_epochs_[i].epoch.load(std::memory_order_acquire);
            if (t_epoch != EPOCH_INACTIVE && t_epoch < current_epoch) {
                return; // An active thread is still in an older epoch
            }
        }
        global_epoch_.compare_exchange_strong(current_epoch, current_epoch + 1,
                                              std::memory_order_acq_rel,
                                              std::memory_order_relaxed);
    }

    // Epoch status check for garbage collection
    bool can_reclaim(uint64_t retired_epoch) const noexcept {
        uint64_t g_epoch = global_epoch_.load(std::memory_order_acquire);
        if (g_epoch < retired_epoch + 2) {
            return false;
        }
        for (size_t i = 0; i < thread_counter_.load(std::memory_order_relaxed); ++i) {
            uint64_t t_epoch = thread_epochs_[i].epoch.load(std::memory_order_acquire);
            if (t_epoch != EPOCH_INACTIVE && t_epoch <= retired_epoch) {
                return false;
            }
        }
        return true;
    }

private:
    EpochManager() : global_epoch_(1), thread_counter_(0) {
        for (size_t i = 0; i < MAX_THREADS; ++i) {
            thread_epochs_[i].epoch.store(EPOCH_INACTIVE, std::memory_order_relaxed);
        }
    }

    struct alignas(hardware_destructive_interference_size) ThreadEpochSlot {
        std::atomic<uint64_t> epoch{EPOCH_INACTIVE};
    };

    alignas(hardware_destructive_interference_size) std::atomic<uint64_t> global_epoch_;
    alignas(hardware_destructive_interference_size) std::atomic<uint32_t> thread_counter_;
    std::array<ThreadEpochSlot, MAX_THREADS> thread_epochs_;
};

// ============================================================================
// Lock-Free Preallocated Thread-Local Arena & Retirement Ring
// ============================================================================
class ThreadSlabAllocator {
public:
    struct RetirementEntry {
        Node*    ptr;
        uint64_t epoch;
    };

    ThreadSlabAllocator(uint32_t thread_id)
        : thread_id_(thread_id), slab_pos_(0), retire_head_(0), retire_tail_(0) {
        // Pre-allocate slab buffer to guarantee zero dynamic allocation on hot path
        storage_ = static_cast<char*>(::operator new[](SLAB_CAPACITY_PER_EPOCH * sizeof(ConsolidatedLeafNode),
                                                       std::align_val_t(hardware_destructive_interference_size)));
    }

    ~ThreadSlabAllocator() {
        process_retirements(true);
        ::operator delete[](storage_, std::align_val_t(hardware_destructive_interference_size));
    }

    template <typename T, typename... Args>
    T* allocate(Args&&... args) {
        constexpr size_t alloc_size = (sizeof(T) + hardware_destructive_interference_size - 1) 
                                      & ~(hardware_destructive_interference_size - 1);
        if (slab_pos_ + alloc_size > SLAB_CAPACITY_PER_EPOCH * sizeof(ConsolidatedLeafNode)) {
            // Reclaim retired items and reset slab ring
            process_retirements(false);
            slab_pos_ = 0;
        }
        void* mem = &storage_[slab_pos_];
        slab_pos_ += alloc_size;
        return new (mem) T(std::forward<Args>(args)...);
    }

    void retire(Node* node) {
        uint64_t epoch = EpochManager::instance().get_global_epoch();
        retire_ring_[retire_tail_ % RETIRE_CAPACITY] = {node, epoch};
        retire_tail_++;
        process_retirements(false);
    }

    void process_retirements(bool force) {
        while (retire_head_ < retire_tail_) {
            auto& entry = retire_ring_[retire_head_ % RETIRE_CAPACITY];
            if (force || EpochManager::instance().can_reclaim(entry.epoch)) {
                if (entry.ptr) {
                    entry.ptr->~Node();
                    entry.ptr = nullptr;
                }
                retire_head_++;
            } else {
                break;
            }
        }
        EpochManager::instance().try_advance_epoch();
    }

private:
    static constexpr size_t RETIRE_CAPACITY = 16384;
    uint32_t thread_id_;
    char*    storage_;
    size_t   slab_pos_;
    size_t   retire_head_;
    size_t   retire_tail_;
    std::array<RetirementEntry, RETIRE_CAPACITY> retire_ring_;
};

thread_local std::optional<uint32_t> local_thread_id;
thread_local std::optional<ThreadSlabAllocator> local_allocator;

inline void ensure_thread_initialized() {
    if (!local_thread_id.has_value()) {
        local_thread_id = EpochManager::instance().register_thread();
        local_allocator.emplace(local_thread_id.value());
    }
}

// RAII Epoch Guard for Transactions
struct EpochGuard {
    EpochGuard() {
        ensure_thread_initialized();
        EpochManager::instance().enter(local_thread_id.value());
    }
    ~EpochGuard() {
        EpochManager::instance().exit(local_thread_id.value());
    }
};

// ============================================================================
// Core Latch-Free Storage Engine Index Subsystem
// ============================================================================
enum class ReadStatus {
    FOUND,
    NOT_FOUND,
    DELETED,
    CONCURRENT_ABORT
};

struct ReadResult {
    ReadStatus status;
    ValueType  value;
};

class LockFreeMVCCIndex {
public:
    LockFreeMVCCIndex() {
        ensure_thread_initialized();
        auto* initial_base = local_allocator->allocate<ConsolidatedLeafNode>();
        root_.store(initial_base, std::memory_order_release);
    }

    // ------------------------------------------------------------------------
    // Read Traversal with MVCC Visibility & Split Routing
    // ------------------------------------------------------------------------
    ReadResult read_record(std::atomic<Node*>& root_slot, KeyType key, TxnTimestamp read_ts) {
        EpochGuard guard; // Protects pointer traversal throughout EBR epoch

        Node* curr = root_slot.load(std::memory_order_acquire);

        while (curr != nullptr) {
            // Split Routing: check if key was shifted to right child via concurrent split
            if (curr->type == NodeType::SPLIT_DELTA) {
                auto* split = static_cast<SplitDelta*>(curr);
                if (key >= split->split_key) {
                    // Navigate to the split child branch
                    curr = split->right_child;
                    continue;
                }
                curr = curr->next;
                continue;
            }

            if (curr->type == NodeType::ABORT_DELTA) {
                auto* abort_node = static_cast<AbortDelta*>(curr);
                if (abort_node->key == key) {
                    // Skip over aborted updates for this key
                    curr = curr->next;
                    continue;
                }
                curr = curr->next;
                continue;
            }

            if (curr->type == NodeType::RECORD_DELTA) {
                auto* delta = static_cast<RecordDelta*>(curr);
                if (delta->key == key) {
                    TxnDescriptor& desc = TxnManager::instance().get_desc(delta->tx_id);
                    TxnState state = desc.state.load(std::memory_order_acquire);

                    if (state == TxnState::COMMITTED) {
                        TxnTimestamp commit_ts = desc.commit_ts.load(std::memory_order_acquire);
                        if (commit_ts <= read_ts) {
                            return {ReadStatus::FOUND, delta->value};
                        }
                    } else if (state == TxnState::ACTIVE && delta->creation_ts <= read_ts) {
                        // Uncommitted optimistic read validation
                        return {ReadStatus::FOUND, delta->value};
                    }
                    // Aborted or non-visible; follow delta chain backwards
                }
                curr = curr->next;
                continue;
            }

            if (curr->type == NodeType::CONSOLIDATED_LEAF) {
                auto* leaf = static_cast<ConsolidatedLeafNode*>(curr);
                // Binary search or linear scan in sorted consolidated slots
                for (uint32_t i = 0; i < leaf->count; ++i) {
                    if (leaf->slots[i].key == key) {
                        if (leaf->slots[i].commit_ts <= read_ts) {
                            return {ReadStatus::FOUND, leaf->slots[i].value};
                        }
                        break;
                    }
                }
                return {ReadStatus::NOT_FOUND, 0};
            }
        }
        return {ReadStatus::NOT_FOUND, 0};
    }

    // ------------------------------------------------------------------------
    // Delta Append: Prepend Insert/Update Record
    // ------------------------------------------------------------------------
    bool append_update(std::atomic<Node*>& target_slot, KeyType key, ValueType value, 
                       TxnId tx_id, TxnTimestamp ts) {
        ensure_thread_initialized();
        EpochGuard guard;

        Node* current_head = target_slot.load(std::memory_order_acquire);
        RecordDelta* new_delta = local_allocator->allocate<RecordDelta>(
            key, value, tx_id, ts, current_head
        );

        // Atomic CAS with Release semantics to publish initialized Delta Record
        while (!target_slot.compare_exchange_weak(
            current_head, new_delta,
            std::memory_order_release,
            std::memory_order_acquire)) {
            new_delta->next = current_head;
        }

        return true;
    }

    // ------------------------------------------------------------------------
    // Transaction Rollback: Prepend AbortDelta & Invalidate In-Flight Updates
    // ------------------------------------------------------------------------
    void abort_transaction(std::atomic<Node*>& target_slot, KeyType key, TxnId tx_id) {
        ensure_thread_initialized();
        EpochGuard guard;

        TxnDescriptor& desc = TxnManager::instance().get_desc(tx_id);
        desc.state.store(TxnState::ABORTED, std::memory_order_release);

        Node* current_head = target_slot.load(std::memory_order_acquire);
        AbortDelta* abort_node = local_allocator->allocate<AbortDelta>(
            key, tx_id, current_head
        );

        while (!target_slot.compare_exchange_weak(
            current_head, abort_node,
            std::memory_order_release,
            std::memory_order_acquire)) {
            abort_node->next = current_head;
        }
    }

    // ------------------------------------------------------------------------
    // Latch-Free Delta Consolidation & Split Routine
    // ------------------------------------------------------------------------
    bool consolidate_and_split(std::atomic<Node*>& root_slot, Node* expected_head) {
        ensure_thread_initialized();
        EpochGuard guard;

        if (expected_head == nullptr) {
            return false;
        }

        // Collect all visible valid KV pairs up to the consolidation horizon
        std::vector<KVPair> valid_entries;
        valid_entries.reserve(MAX_KEYS_PER_LEAF * 2);

        Node* curr = expected_head;
        std::vector<Node*> chain_nodes;

        while (curr != nullptr) {
            chain_nodes.push_back(curr);
            if (curr->type == NodeType::RECORD_DELTA) {
                auto* delta = static_cast<RecordDelta*>(curr);
                TxnDescriptor& desc = TxnManager::instance().get_desc(delta->tx_id);
                TxnState state = desc.state.load(std::memory_order_acquire);

                if (state == TxnState::COMMITTED) {
                    bool exists = false;
                    for (const auto& kv : valid_entries) {
                        if (kv.key == delta->key) { exists = true; break; }
                    }
                    if (!exists) {
                        valid_entries.push_back({delta->key, delta->value, desc.commit_ts.load(std::memory_order_relaxed)});
                    }
                }
            } else if (curr->type == NodeType::CONSOLIDATED_LEAF) {
                auto* leaf = static_cast<ConsolidatedLeafNode*>(curr);
                for (uint32_t i = 0; i < leaf->count; ++i) {
                    bool exists = false;
                    for (const auto& kv : valid_entries) {
                        if (kv.key == leaf->slots[i].key) { exists = true; break; }
                    }
                    if (!exists) {
                        valid_entries.push_back(leaf->slots[i]);
                    }
                }
                break; // Base reached
            }
            curr = curr->next;
        }

        // Sort keys to maintain ordered invariants
        std::sort(valid_entries.begin(), valid_entries.end(), [](const KVPair& a, const KVPair& b) {
            return a.key < b.key;
        });

        // Determine if node requires a split
        if (valid_entries.size() > MAX_KEYS_PER_LEAF) {
            size_t mid = valid_entries.size() / 2;
            KeyType split_key = valid_entries[mid].key;

            // Allocate left and right consolidated base leaves
            auto* left_node = local_allocator->allocate<ConsolidatedLeafNode>();
            auto* right_node = local_allocator->allocate<ConsolidatedLeafNode>();

            left_node->count = static_cast<uint32_t>(mid);
            for (size_t i = 0; i < mid; ++i) {
                left_node->slots[i] = valid_entries[i];
            }

            right_node->count = static_cast<uint32_t>(valid_entries.size() - mid);
            for (size_t i = mid; i < valid_entries.size(); ++i) {
                right_node->slots[i - mid] = valid_entries[i];
            }

            // Install SplitDelta pointing to right child atop left base node
            auto* split_delta = local_allocator->allocate<SplitDelta>(split_key, right_node, left_node);

            // Attempt CAS replacement of old delta chain head
            if (root_slot.compare_exchange_strong(
                expected_head, split_delta,
                std::memory_order_acq_rel,
                std::memory_order_acquire)) {

                // Enqueue replaced delta chain nodes for EBR retirement
                for (Node* old_node : chain_nodes) {
                    local_allocator->retire(old_node);
                }
                return true;
            }
        } else {
            // Standard consolidation without split
            auto* consolidated = local_allocator->allocate<ConsolidatedLeafNode>();
            consolidated->count = static_cast<uint32_t>(valid_entries.size());
            for (size_t i = 0; i < valid_entries.size(); ++i) {
                consolidated->slots[i] = valid_entries[i];
            }

            if (root_slot.compare_exchange_strong(
                expected_head, consolidated,
                std::memory_order_acq_rel,
                std::memory_order_acquire)) {

                for (Node* old_node : chain_nodes) {
                    local_allocator->retire(old_node);
                }
                return true;
            }
        }

        return false; // CAS failed due to concurrent modification
    }

    std::atomic<Node*>& get_root() { return root_; }

private:
    alignas(hardware_destructive_interference_size) std::atomic<Node*> root_{nullptr};
};

