### Complete Production-Grade Implementation (C++20)

```cpp
#include <iostream>
#include <atomic>
#include <vector>
#include <optional>
#include <memory>
#include <thread>
#include <concepts>
#include <algorithm>
#include <cstdint>
#include <cassert>
#include <cstring>
#include <array>
#include <new>

// ============================================================================
// 1. HARDWARE ARCHITECTURE & CONFIGURATION CONSTANTS
// ============================================================================
#if defined(__cpp_lib_hardware_interference_size)
    using std::hardware_destructive_interference_size;
#else
    constexpr size_t hardware_destructive_interference_size = 64;
#endif

constexpr size_t MAX_DELTA_CHAIN_LENGTH = 8;
constexpr size_t MAX_BASE_NODE_CAPACITY  = 16;
constexpr size_t MAX_THREADS            = 128;
constexpr size_t MAX_HAZARD_PER_THREAD  = 4;
constexpr size_t MAX_MAPPING_SLOTS      = 65536;

using NodeID    = uint64_t;
using Timestamp = uint64_t;

// Tag masks (lowest 3 bits)
constexpr uintptr_t TAG_MASK   = 0x7;
constexpr uintptr_t PTR_MASK   = ~TAG_MASK;

enum NodeType : uintptr_t {
    BASE_LEAF   = 0x0,
    BASE_INNER  = 0x1,
    DELTA_INSERT= 0x2,
    DELTA_DELETE= 0x3,
    DELTA_SPLIT = 0x4,
    NODE_DEAD   = 0x5
};

inline uintptr_t TagPointer(void* ptr, NodeType type) {
    return reinterpret_cast<uintptr_t>(ptr) | static_cast<uintptr_t>(type);
}

inline void* UntagPointer(uintptr_t tagged) {
    return reinterpret_cast<void*>(tagged & PTR_MASK);
}

inline NodeType GetNodeType(uintptr_t tagged) {
    return static_cast<NodeType>(tagged & TAG_MASK);
}

// ============================================================================
// 2. SAFE MEMORY RECLAMATION (HYBRID HAZARD POINTER + EPOCH RETIREMENT)
// ============================================================================
struct alignas(hardware_destructive_interference_size) HazardSlot {
    std::atomic<void*> hazard_ptrs[MAX_HAZARD_PER_THREAD];
    std::atomic<bool>  active{false};

    HazardSlot() {
        for (auto& hp : hazard_ptrs) hp.store(nullptr, std::memory_order_relaxed);
    }
};

class HazardRegistry {
public:
    static HazardRegistry& Instance() {
        static HazardRegistry registry;
        return registry;
    }

    size_t RegisterThread() {
        for (size_t i = 0; i < MAX_THREADS; ++i) {
            bool expected = false;
            if (slots_[i].active.compare_exchange_strong(expected, true, std::memory_order_acq_rel)) {
                return i;
            }
        }
        throw std::runtime_error("HazardRegistry: Exceeded MAX_THREADS");
    }

    void UnregisterThread(size_t thread_id) {
        for (auto& hp : slots_[thread_id].hazard_ptrs) {
            hp.store(nullptr, std::memory_order_release);
        }
        slots_[thread_id].active.store(false, std::memory_order_release);
    }

    void SetHazard(size_t thread_id, size_t slot_idx, void* ptr) {
        assert(slot_idx < MAX_HAZARD_PER_THREAD);
        slots_[thread_id].hazard_ptrs[slot_idx].store(ptr, std::memory_order_release);
    }

    void ClearHazard(size_t thread_id, size_t slot_idx) {
        assert(slot_idx < MAX_HAZARD_PER_THREAD);
        slots_[thread_id].hazard_ptrs[slot_idx].store(nullptr, std::memory_order_release);
    }

    void ClearAllHazards(size_t thread_id) {
        for (size_t i = 0; i < MAX_HAZARD_PER_THREAD; ++i) {
            slots_[thread_id].hazard_ptrs[i].store(nullptr, std::memory_order_release);
        }
    }

    bool IsHazardous(void* ptr) const {
        for (size_t i = 0; i < MAX_THREADS; ++i) {
            if (!slots_[i].active.load(std::memory_order_acquire)) continue;
            for (size_t j = 0; j < MAX_HAZARD_PER_THREAD; ++j) {
                if (slots_[i].hazard_ptrs[j].load(std::memory_order_acquire) == ptr) {
                    return true;
                }
            }
        }
        return false;
    }

private:
    HazardRegistry() = default;
    alignas(hardware_destructive_interference_size) HazardSlot slots_[MAX_THREADS];
};

// Epoch Reclamation Unit for Retired Buffers
struct RetiredNode {
    void* ptr;
    void (*deleter)(void*);
};

class ThreadLocalSMR {
public:
    ThreadLocalSMR() {
        thread_id_ = HazardRegistry::Instance().RegisterThread();
    }

    ~ThreadLocalSMR() {
        ReclaimAll();
        HazardRegistry::Instance().UnregisterThread(thread_id_);
    }

    size_t GetThreadId() const { return thread_id_; }

    void SetHP(size_t slot_idx, void* ptr) {
        HazardRegistry::Instance().SetHazard(thread_id_, slot_idx, ptr);
    }

    void ClearHP(size_t slot_idx) {
        HazardRegistry::Instance().ClearHazard(thread_id_, slot_idx);
    }

    void ClearAllHP() {
        HazardRegistry::Instance().ClearAllHazards(thread_id_);
    }

    template <typename T>
    void Retire(T* ptr) {
        retire_list_.push_back({
            ptr,
            [](void* p) { delete static_cast<T*>(p); }
        });
        if (retire_list_.size() >= 32) {
            Reclaim();
        }
    }

    void Reclaim() {
        auto it = retire_list_.begin();
        while (it != retire_list_.end()) {
            if (!HazardRegistry::Instance().IsHazardous(it->ptr)) {
                it->deleter(it->ptr);
                it = retire_list_.erase(it);
            } else {
                ++it;
            }
        }
    }

    void ReclaimAll() {
        while (!retire_list_.empty()) {
            Reclaim();
            if (!retire_list_.empty()) {
                std::this_thread::yield();
            }
        }
    }

private:
    size_t thread_id_;
    std::vector<RetiredNode> retire_list_;
};

static thread_local ThreadLocalSMR t_smr;

// Guard helper for RAII Hazard Pointer management
struct HazardGuard {
    size_t slot;
    HazardGuard(size_t s, void* ptr) : slot(s) {
        t_smr.SetHP(slot, ptr);
    }
    ~HazardGuard() {
        t_smr.ClearHP(slot);
    }
    void Update(void* ptr) {
        t_smr.SetHP(slot, ptr);
    }
};

// ============================================================================
// 3. TREE NODE STRUCTURES & DELTA RECORDS
// ============================================================================
template <typename K, typename V>
struct alignas(hardware_destructive_interference_size) BaseNode {
    bool is_leaf;
    size_t count;
    std::optional<K> high_key;
    NodeID right_sibling_id;

    // Keys & Values / Child NodeIDs
    std::array<K, MAX_BASE_NODE_CAPACITY> keys;
    std::array<V, MAX_BASE_NODE_CAPACITY> values;
    std::array<NodeID, MAX_BASE_NODE_CAPACITY + 1> children;

    BaseNode(bool leaf) 
        : is_leaf(leaf), count(0), right_sibling_id(0) {}
};

template <typename K, typename V>
struct alignas(hardware_destructive_interference_size) InsertDeltaNode {
    Timestamp tx_id;
    K key;
    V value;
    uintptr_t prev_physical;

    InsertDeltaNode(Timestamp tx, const K& k, const V& v, uintptr_t prev)
        : tx_id(tx), key(k), value(v), prev_physical(prev) {}
};

template <typename K>
struct alignas(hardware_destructive_interference_size) DeleteDeltaNode {
    Timestamp tx_id;
    K key;
    uintptr_t prev_physical;

    DeleteDeltaNode(Timestamp tx, const K& k, uintptr_t prev)
        : tx_id(tx), key(k), prev_physical(prev) {}
};

template <typename K>
struct alignas(hardware_destructive_interference_size) SplitDeltaNode {
    K split_key;
    NodeID right_sibling_id;
    uintptr_t prev_physical;

    SplitDeltaNode(const K& sk, NodeID right_id, uintptr_t prev)
        : split_key(sk), right_sibling_id(right_id), prev_physical(prev) {}
};

// ============================================================================
// 4. ATOMIC MAPPING TABLE
// ============================================================================
class MappingTable {
public:
    MappingTable() {
        for (size_t i = 0; i < MAX_MAPPING_SLOTS; ++i) {
            entries_[i].store(0, std::memory_order_relaxed);
        }
        allocated_count_.store(1, std::memory_order_relaxed); // NodeID 0 reserved
    }

    NodeID AllocateSlot() {
        NodeID id = allocated_count_.fetch_add(1, std::memory_order_relaxed);
        if (id >= MAX_MAPPING_SLOTS) {
            throw std::runtime_error("MappingTable: Out of node slots");
        }
        return id;
    }

    uintptr_t GetPhysical(NodeID id, std::memory_order order = std::memory_order_acquire) const {
        assert(id < MAX_MAPPING_SLOTS);
        return entries_[id].load(order);
    }

    bool CAS(NodeID id, uintptr_t& expected, uintptr_t desired, 
             std::memory_order success_order = std::memory_order_acq_rel, 
             std::memory_order failure_order = std::memory_order_acquire) {
        assert(id < MAX_MAPPING_SLOTS);
        return entries_[id].compare_exchange_strong(expected, desired, success_order, failure_order);
    }

    void Install(NodeID id, uintptr_t physical) {
        assert(id < MAX_MAPPING_SLOTS);
        entries_[id].store(physical, std::memory_order_release);
    }

private:
    alignas(hardware_destructive_interference_size) std::atomic<uintptr_t> entries_[MAX_MAPPING_SLOTS];
    alignas(hardware_destructive_interference_size) std::atomic<NodeID> allocated_count_;
};

// ============================================================================
// 5. CONCURRENT MULTI-VERSION BW-TREE CORE ENGINE
// ============================================================================
template <typename K, typename V>
    requires std::totally_ordered<K>
class MVBwTree {
public:
    MVBwTree() {
        root_id_ = mapping_table_.AllocateSlot();
        auto* root_base = new BaseNode<K, V>(true);
        mapping_table_.Install(root_id_, TagPointer(root_base, BASE_LEAF));
    }

    ~MVBwTree() {
        // Cleanup all reachable allocated nodes across mapping table
        for (size_t i = 1; i < MAX_MAPPING_SLOTS; ++i) {
            uintptr_t head = mapping_table_.GetPhysical(i, std::memory_order_relaxed);
            FreeChainUnsafe(head);
        }
        t_smr.ReclaimAll();
    }

    // ------------------------------------------------------------------------
    // Read Path: Wait-Free MVCC Point Lookup
    // ------------------------------------------------------------------------
    std::optional<V> Lookup(const K& key, Timestamp read_ts) {
        while (true) {
            NodeID cur_id = root_id_;

            while (true) {
                uintptr_t cur_tagged = mapping_table_.GetPhysical(cur_id, std::memory_order_acquire);
                void* raw_ptr = UntagPointer(cur_tagged);

                // Hazard pointer publication with memory fence
                t_smr.SetHP(0, raw_ptr);
                std::atomic_thread_fence(std::memory_order_seq_cst);

                if (mapping_table_.GetPhysical(cur_id, std::memory_order_acquire) != cur_tagged) {
                    continue; // Raced with CAS, retry node resolution
                }

                // Follow delta chain to search or hop sibling
                bool hopped = false;
                uintptr_t chain_walker = cur_tagged;

                while (chain_walker != 0) {
                    NodeType type = GetNodeType(chain_walker);
                    void* ptr = UntagPointer(chain_walker);

                    if (type == DELTA_SPLIT) {
                        auto* split = static_cast<SplitDeltaNode<K>*>(ptr);
                        if (key >= split->split_key) {
                            cur_id = split->right_sibling_id;
                            hopped = true;
                            break; // Hop right to sibling
                        }
                        chain_walker = split->prev_physical;
                    } else if (type == DELTA_INSERT) {
                        auto* ins = static_cast<InsertDeltaNode<K, V>*>(ptr);
                        if (ins->key == key && ins->tx_id <= read_ts) {
                            t_smr.ClearAllHP();
                            return ins->value; // MVCC hit
                        }
                        chain_walker = ins->prev_physical;
                    } else if (type == DELTA_DELETE) {
                        auto* del = static_cast<DeleteDeltaNode<K>*>(ptr);
                        if (del->key == key && del->tx_id <= read_ts) {
                            t_smr.ClearAllHP();
                            return std::nullopt; // Tombstone hit
                        }
                        chain_walker = del->prev_physical;
                    } else if (type == BASE_LEAF) {
                        auto* base = static_cast<BaseNode<K, V>*>(ptr);
                        if (base->high_key.has_value() && key >= *base->high_key && base->right_sibling_id != 0) {
                            cur_id = base->right_sibling_id;
                            hopped = true;
                            break;
                        }
                        for (size_t i = 0; i < base->count; ++i) {
                            if (base->keys[i] == key) {
                                V val = base->values[i];
                                t_smr.ClearAllHP();
                                return val;
                            }
                        }
                        t_smr.ClearAllHP();
                        return std::nullopt;
                    } else if (type == BASE_INNER) {
                        auto* inner = static_cast<BaseNode<K, V>*>(ptr);
                        if (inner->high_key.has_value() && key >= *inner->high_key && inner->right_sibling_id != 0) {
                            cur_id = inner->right_sibling_id;
                            hopped = true;
                            break;
                        }
                        // Route down
                        size_t idx = 0;
                        while (idx < inner->count && key >= inner->keys[idx]) {
                            idx++;
                        }
                        cur_id = inner->children[idx];
                        hopped = true;
                        break;
                    } else {
                        break;
                    }
                }

                if (hopped) {
                    continue; // Traverse into next child or right sibling
                }

                t_smr.ClearAllHP();
                return std::nullopt;
            }
        }
    }

    // ------------------------------------------------------------------------
    // Write Path: Lock-Free Prepend Insertion
    // ------------------------------------------------------------------------
    bool Insert(const K& key, const V& val, Timestamp commit_ts) {
        while (true) {
            NodeID leaf_id = LocateLeaf(key);
            uintptr_t head = mapping_table_.GetPhysical(leaf_id, std::memory_order_acquire);

            // Check chain depth for consolidation threshold
            size_t depth = MeasureDeltaDepth(head);
            if (depth >= MAX_DELTA_CHAIN_LENGTH) {
                ConsolidateLeaf(leaf_id);
                continue;
            }

            auto* delta = new InsertDeltaNode<K, V>(commit_ts, key, val, head);
            uintptr_t new_head = TagPointer(delta, DELTA_INSERT);

            if (mapping_table_.CAS(leaf_id, head, new_head)) {
                return true;
            }

            delete delta; // CAS failed, retry
        }
    }

    // ------------------------------------------------------------------------
    // Write Path: Lock-Free Tombstone Deletion
    // ------------------------------------------------------------------------
    bool Remove(const K& key, Timestamp commit_ts) {
        while (true) {
            NodeID leaf_id = LocateLeaf(key);
            uintptr_t head = mapping_table_.GetPhysical(leaf_id, std::memory_order_acquire);

            size_t depth = MeasureDeltaDepth(head);
            if (depth >= MAX_DELTA_CHAIN_LENGTH) {
                ConsolidateLeaf(leaf_id);
                continue;
            }

            auto* delta = new DeleteDeltaNode<K>(commit_ts, key, head);
            uintptr_t new_head = TagPointer(delta, DELTA_DELETE);

            if (mapping_table_.CAS(leaf_id, head, new_head)) {
                return true;
            }

            delete delta; // CAS failed, retry
        }
    }

    // ------------------------------------------------------------------------
    // Scan Path: Wait-Free MVCC Range Scan across Sibling Links
    // ------------------------------------------------------------------------
    template <typename OutputIter>
    size_t RangeScan(const K& start_key, const K& end_key, Timestamp read_ts, OutputIter out) {
        size_t matches = 0;
        NodeID cur_id = LocateLeaf(start_key);

        while (cur_id != 0) {
            uintptr_t cur_tagged = mapping_table_.GetPhysical(cur_id, std::memory_order_acquire);
            void* raw_ptr = UntagPointer(cur_tagged);

            t_smr.SetHP(0, raw_ptr);
            std::atomic_thread_fence(std::memory_order_seq_cst);

            if (mapping_table_.GetPhysical(cur_id, std::memory_order_acquire) != cur_tagged) {
                continue; // Retry concurrent modification
            }

            // Materialize leaf state locally
            std::vector<std::pair<K, V>> items;
            NodeID next_sibling = 0;
            std::optional<K> high_key;

            MaterializeLeafState(cur_tagged, read_ts, items, high_key, next_sibling);

            for (const auto& [k, v] : items) {
                if (k >= start_key && k <= end_key) {
                    *out++ = {k, v};
                    matches++;
                }
            }

            if (high_key.has_value() && *high_key > end_key) {
                break; // Reached upper scan boundary
            }

            cur_id = next_sibling;
        }

        t_smr.ClearAllHP();
        return matches;
    }

    // ------------------------------------------------------------------------
    // SMO: Single-CAS Leaf Consolidation & Split
    // ------------------------------------------------------------------------
    bool ConsolidateLeaf(NodeID node_id) {
        uintptr_t head = mapping_table_.GetPhysical(node_id, std::memory_order_acquire);
        if (head == 0) return false;

        void* raw_ptr = UntagPointer(head);
        t_smr.SetHP(0, raw_ptr);
        std::atomic_thread_fence(std::memory_order_seq_cst);

        if (mapping_table_.GetPhysical(node_id, std::memory_order_acquire) != head) {
            t_smr.ClearHP(0);
            return false;
        }

        std::vector<std::pair<K, V>> consolidated_items;
        NodeID next_sibling = 0;
        std::optional<K> high_key;

        // Fold delta chain from newest to oldest
        MaterializeLeafState(head, UINT64_MAX, consolidated_items, high_key, next_sibling);

        // Check if split is required
        if (consolidated_items.size() > MAX_BASE_NODE_CAPACITY) {
            size_t mid = consolidated_items.size() / 2;
            K split_key = consolidated_items[mid].first;

            // 1. Create right sibling base node
            auto* right_base = new BaseNode<K, V>(true);
            right_base->count = consolidated_items.size() - mid;
            right_base->high_key = high_key;
            right_base->right_sibling_id = next_sibling;
            for (size_t i = mid; i < consolidated_items.size(); ++i) {
                right_base->keys[i - mid] = consolidated_items[i].first;
                right_base->values[i - mid] = consolidated_items[i].second;
            }

            NodeID right_id = mapping_table_.AllocateSlot();
            mapping_table_.Install(right_id, TagPointer(right_base, BASE_LEAF));

            // 2. Create new left base node
            auto* left_base = new BaseNode<K, V>(true);
            left_base->count = mid;
            left_base->high_key = split_key;
            left_base->right_sibling_id = right_id;
            for (size_t i = 0; i < mid; ++i) {
                left_base->keys[i] = consolidated_items[i].first;
                left_base->values[i] = consolidated_items[i].second;
            }

            // 3. Atomically replace left node via single CAS
            uintptr_t new_left = TagPointer(left_base, BASE_LEAF);
            if (mapping_table_.CAS(node_id, head, new_left)) {
                RetireDeltaChain(head);
                t_smr.ClearHP(0);
                return true;
            } else {
                // Split aborted by concurrent CAS
                delete left_base;
                delete right_base;
                t_smr.ClearHP(0);
                return false;
            }
        } else {
            // Standard In-place consolidation without split
            auto* new_base = new BaseNode<K, V>(true);
            new_base->count = consolidated_items.size();
            new_base->high_key = high_key;
            new_base->right_sibling_id = next_sibling;
            for (size_t i = 0; i < consolidated_items.size(); ++i) {
                new_base->keys[i] = consolidated_items[i].first;
                new_base->values[i] = consolidated_items[i].second;
            }

            uintptr_t new_head = TagPointer(new_base, BASE_LEAF);
            if (mapping_table_.CAS(node_id, head, new_head)) {
                RetireDeltaChain(head);
                t_smr.ClearHP(0);
                return true;
            } else {
                delete new_base;
                t_smr.ClearHP(0);
                return false;
            }
        }
    }

private:
    NodeID root_id_;
    MappingTable mapping_table_;

    NodeID LocateLeaf(const K& key) {
        NodeID cur_id = root_id_;
        while (true) {
            uintptr_t cur_tagged = mapping_table_.GetPhysical(cur_id, std::memory_order_acquire);
            NodeType type = GetNodeType(cur_tagged);
            void* raw_ptr = UntagPointer(cur_tagged);

            if (type == BASE_LEAF || type == DELTA_INSERT || type == DELTA_DELETE || type == DELTA_SPLIT) {
                // Check if high-key requires sibling hop
                if (type == DELTA_SPLIT) {
                    auto* split = static_cast<SplitDeltaNode<K>*>(raw_ptr);
                    if (key >= split->split_key) {
                        cur_id = split->right_sibling_id;
                        continue;
                    }
                }
                return cur_id; // Found target leaf
            } else if (type == BASE_INNER) {
                auto* inner = static_cast<BaseNode<K, V>*>(raw_ptr);
                if (inner->high_key.has_value() && key >= *inner->high_key && inner->right_sibling_id != 0) {
                    cur_id = inner->right_sibling_id;
                    continue;
                }
                size_t idx = 0;
                while (idx < inner->count && key >= inner->keys[idx]) {
                    idx++;
                }
                cur_id = inner->children[idx];
            } else {
                return cur_id;
            }
        }
    }

    size_t MeasureDeltaDepth(uintptr_t head) {
        size_t depth = 0;
        uintptr_t cur = head;
        while (cur != 0 && GetNodeType(cur) != BASE_LEAF && GetNodeType(cur) != BASE_INNER) {
            depth++;
            NodeType type = GetNodeType(cur);
            void* ptr = UntagPointer(cur);
            if (type == DELTA_INSERT) {
                cur = static_cast<InsertDeltaNode<K, V>*>(ptr)->prev_physical;
            } else if (type == DELTA_DELETE) {
                cur = static_cast<DeleteDeltaNode<K>*>(ptr)->prev_physical;
            } else if (type == DELTA_SPLIT) {
                cur = static_cast<SplitDeltaNode<K>*>(ptr)->prev_physical;
            } else {
                break;
            }
        }
        return depth;
    }

    void MaterializeLeafState(uintptr_t head, Timestamp read_ts, 
                              std::vector<std::pair<K, V>>& items, 
                              std::optional<K>& high_key, 
                              NodeID& next_sibling) {
        std::vector<uintptr_t> chain;
        uintptr_t cur = head;
        while (cur != 0) {
            chain.push_back(cur);
            NodeType type = GetNodeType(cur);
            void* ptr = UntagPointer(cur);
            if (type == DELTA_INSERT) {
                cur = static_cast<InsertDeltaNode<K, V>*>(ptr)->prev_physical;
            } else if (type == DELTA_DELETE) {
                cur = static_cast<DeleteDeltaNode<K>*>(ptr)->prev_physical;
            } else if (type == DELTA_SPLIT) {
                cur = static_cast<SplitDeltaNode<K>*>(ptr)->prev_physical;
            } else {
                break; // Reached BaseNode
            }
        }

        // Apply bottom-up from BaseNode to newest Delta
        std::vector<std::pair<K, std::optional<V>>> delta_ops;
        for (auto it = chain.rbegin(); it != chain.rend(); ++it) {
            NodeType type = GetNodeType(*it);
            void* ptr = UntagPointer(*it);

            if (type == BASE_LEAF) {
                auto* base = static_cast<BaseNode<K, V>*>(ptr);
                high_key = base->high_key;
                next_sibling = base->right_sibling_id;
                for (size_t i = 0; i < base->count; ++i) {
                    items.push_back({base->keys[i], base->values[i]});
                }
            } else if (type == DELTA_SPLIT) {
                auto* split = static_cast<SplitDeltaNode<K>*>(ptr);
                high_key = split->split_key;
                next_sibling = split->right_sibling_id;
            } else if (type == DELTA_INSERT) {
                auto* ins = static_cast<InsertDeltaNode<K, V>*>(ptr);
                if (ins->tx_id <= read_ts) {
                    delta_ops.push_back({ins->key, ins->value});
                }
            } else if (type == DELTA_DELETE) {
                auto* del = static_cast<DeleteDeltaNode<K>*>(ptr);
                if (del->tx_id <= read_ts) {
                    delta_ops.push_back({del->key, std::nullopt});
                }
            }
        }

        // Fold delta operations onto base array
        for (const auto& [k, opt_v] : delta_ops) {
            auto elem = std::find_if(items.begin(), items.end(), [&](const auto& p) { return p.first == k; });
            if (opt_v.has_value()) {
                if (elem != items.end()) {
                    elem->second = *opt_v;
                } else {
                    items.push_back({k, *opt_v});
                }
            } else {
                if (elem != items.end()) {
                    items.erase(elem);
                }
            }
        }

        std::sort(items.begin(), items.end(), [](const auto& a, const auto& b) { return a.first < b.first; });
    }

    void RetireDeltaChain(uintptr_t head) {
        uintptr_t cur = head;
        while (cur != 0) {
            NodeType type = GetNodeType(cur);
            void* ptr = UntagPointer(cur);
            uintptr_t prev = 0;

            if (type == DELTA_INSERT) {
                auto* n = static_cast<InsertDeltaNode<K, V>*>(ptr);
                prev = n->prev_physical;
                t_smr.Retire(n);
            } else if (type == DELTA_DELETE) {
                auto* n = static_cast<DeleteDeltaNode<K>*>(ptr);
                prev = n->prev_physical;
                t_smr.Retire(n);
            } else if (type == DELTA_SPLIT) {
                auto* n = static_cast<SplitDeltaNode<K>*>(ptr);
                prev = n->prev_physical;
                t_smr.Retire(n);
            } else if (type == BASE_LEAF || type == BASE_INNER) {
                auto* n = static_cast<BaseNode<K, V>*>(ptr);
                t_smr.Retire(n);
                break;
            }
            cur = prev;
        }
    }

    void FreeChainUnsafe(uintptr_t head) {
        uintptr_t cur = head;
        while (cur != 0) {
            NodeType type = GetNodeType(cur);
            void* ptr = UntagPointer(cur);
            uintptr_t prev = 0;

            if (type == DELTA_INSERT) {
                auto* n = static_cast<InsertDeltaNode<K, V>*>(ptr);
                prev = n->prev_physical;
                delete n;
            } else if (type == DELTA_DELETE) {
                auto* n = static_cast<DeleteDeltaNode<K>*>(ptr);
                prev = n->prev_physical;
                delete n;
            } else if (type == DELTA_SPLIT) {
                auto* n = static_cast<SplitDeltaNode<K>*>(ptr);
                prev = n->prev_physical;
                delete n;
            } else if (type == BASE_LEAF || type == BASE_INNER) {
                auto* n = static_cast<BaseNode<K, V>*>(ptr);
                delete n;
                break;
            }
            cur = prev;
        }
    }
};

// ============================================================================
// 6. MULTI-THREADED VALIDATION & STRESS TEST HARNESS
// ============================================================================
#include <random>
#include <chrono>

int main() {
    std::cout << "==============================================================\n";
    std::cout << "  MV-Bw-Tree Concurrent High-Contention Stress Validation   \n";
    std::cout << "==============================================================\n";

    MVBwTree<uint64_t, uint64_t> tree;
    constexpr size_t NUM_THREADS = 16;
    constexpr size_t OPS_PER_THREAD = 20000;
    constexpr uint64_t KEY_SPACE = 500; // Force high Zipfian-like collisions

    std::atomic<bool> start_flag{false};
    std::atomic<uint64_t> global_ts{1};
    std::atomic<size_t> successful_lookups{0};
    std::atomic<size_t> successful_inserts{0};
    std::atomic<size_t> successful_scans{0};

    auto WorkerThread = [&](size_t thread_id) {
        // Fast thread-local PRNG
        std::mt19937_64 rng(1337 + thread_id);
        std::exponential_distribution<double> zipf(2.0);

