## 3. High-Concurrency Stress Benchmark & Harness

```cpp
#include <iostream>
#include <vector>
#include <thread>
#include <chrono>
#include <algorithm>
#include <iomanip>
#include <numeric>

int main(int argc, char* argv[]) {
    const size_t NUM_THREADS = (argc > 1) ? std::stoul(argv[1]) : 16;
    const size_t OPS_PER_THREAD = (argc > 2) ? std::stoul(argv[2]) : 200000;
    const std::string wal_file = "/tmp/mvcc_wal.log";

    std::cout << "========================================================================\n";
    std::cout << "  MVCC Engine Benchmark: Lock-Free SkipList + EBR + io_uring WAL\n";
    std::cout << "  Threads: " << NUM_THREADS << " | Ops/Thread: " << OPS_PER_THREAD << "\n";
    std::cout << "========================================================================\n";

    auto& ebr = mvcc::EpochManager::Instance();
    std::unique_ptr<mvcc::MVCCStorageEngine> engine = std::make_unique<mvcc::MVCCStorageEngine>(wal_file);

    std::vector<std::thread> workers;
    std::vector<std::vector<uint64_t>> latencies_us(NUM_THREADS);
    std::atomic<bool> start_signal{false};

    for (size_t t = 0; t < NUM_THREADS; ++t) {
        workers.emplace_back([&, t]() {
            size_t tid = ebr.RegisterThread();
            latencies_us[t].reserve(OPS_PER_THREAD);

            while (!start_signal.load(std::memory_order_acquire)) {
                #if defined(__x86_64__) || defined(_M_X64)
                _mm_pause();
                #endif
            }

            std::mt19937_64 rng(42 + tid);
            std::uniform_int_distribution<uint64_t> key_dist(1, 50000);
            std::uniform_int_distribution<int> op_dist(0, 99);

            for (size_t i = 0; i < OPS_PER_THREAD; ++i) {
                auto t0 = std::chrono::steady_clock::now();
                uint64_t k = key_dist(rng);
                std::string key = "key_" + std::to_string(k);

                int op = op_dist(rng);
                if (op < 70) {
                    // 70% Point Read (MVCC snapshot)
                    mvcc::TxTimestamp read_ts = engine->BeginTransaction();
                    auto res = engine->Get(key, read_ts, tid);
                } else if (op < 95) {
                    // 25% Insert/Update with WAL Flush
                    std::string val = "val_" + std::to_string(i);
                    engine->Put(key, val, tid);
                } else {
                    // 5% Deletion
                    engine->Delete(key, tid);
                }
                auto t1 = std::chrono::steady_clock::now();
                uint64_t dur = std::chrono::duration_cast<std::chrono::microseconds>(t1 - t0).count();
                latencies_us[t].push_back(dur);
            }

            ebr.DeregisterThread(tid);
        });
    }

    auto start_time = std::chrono::high_resolution_clock::now();
    start_signal.store(true, std::memory_order_release);

    for (auto& w : workers) {
        w.join();
    }
    auto end_time = std::chrono::high_resolution_clock::now();

    double total_sec = std::chrono::duration<double>(end_time - start_time).count();
    size_t total_ops = NUM_THREADS * OPS_PER_THREAD;
    double ops_per_sec = static_cast<double>(total_ops) / total_sec;

    std::vector<uint64_t> all_latencies;
    all_latencies.reserve(total_ops);
    for (const auto& l : latencies_us) {
        all_latencies.insert(all_latencies.end(), l.begin(), l.end());
    }
    std::sort(all_latencies.begin(), all_latencies.end());

    uint64_t p50 = all_latencies[all_latencies.size() * 0.50];
    uint64_t p90 = all_latencies[all_latencies.size() * 0.90];
    uint64_t p99 = all_latencies[all_latencies.size() * 0.99];
    uint64_t p999 = all_latencies[all_latencies.size() * 0.999];

    std::cout << std::fixed << std::setprecision(2);
    std::cout << "\n--- Performance Results ---\n";
    std::cout << "Elapsed Time:       " << total_sec << " s\n";
    std::cout << "Aggregate Ops:      " << total_ops << " ops\n";
    std::cout << "Throughput:         " << (ops_per_sec / 1e6) << " Million Ops/sec\n";
    std::cout << "\n--- Tail Latency Profile ---\n";
    std::cout << "p50:  " << p50 << " us\n";
    std::cout << "p90:  " << p90 << " us\n";
    std::cout << "p99:  " << p99 << " us\n";
    std::cout << "p99.9:" << p999 << " us\n";

    // Destroy current engine and run crash recovery
    engine.reset();
    std::cout << "\nStarting WAL Crash Replay Verification...\n";
    mvcc::ConcurrentSkipListMap<std::string> recovered_index;
    size_t rec_tid = ebr.RegisterThread();
    mvcc::MVCCStorageEngine::Recover(wal_file, recovered_index, rec_tid);
    ebr.DeregisterThread(rec_tid);
    std::cout << "Recovery benchmark completed successfully.\n";

    return 0;
}
