# High-Performance Lock-Free MVCC Skip-List with Dual-Epoch Safe Memory Reclamation

This document provides the complete, production-grade C++20 implementation of a lock-free Multi-Version Concurrency Control (MVCC) Skip-List index. The architecture combines an adaptation of the **Fraser-Fomitchev lock-free skip-list algorithm**, **Dual-Epoch Safe Memory Reclamation (EBR)**, **decentralized NUMA-friendly thread registration**, **snapshot-isolated range queries**, and an **asynchronous multi-version garbage collection engine**.

---

## Architecture Overview

```
                      +-------------------------------------------------------------+
                      |                      MVCCSkipList                           |
                      +-------------------------------------------------------------+
                                                     |
         +-------------------------------------------+-------------------------------------------+
         |                                                                                       |
         v                                                                                       v
+-----------------------------+                                                     +-----------------------------+
|    Fraser-Fomitchev Tower   |                                                     |   Dual-Epoch SMR Engine     |
|   (Lock-Free Index Levels)  |                                                     |  (EpochReclaimer & Guards)  |
+-----------------------------+                                                     +-----------------------------+
| L3: [Head] --------------> [Node A] ------------------------------------> [Tail]  | - Global Epoch: E           |
| L2: [Head] --------------> [Node A] -------------------> [Node C] ------> [Tail]  | - Thread-Local Epoch Buffers|
| L1: [Head] --------------> [Node A] ------> [Node B] --> [Node C] ------> [Tail]  | - Bounded Retirement Rings  |
| L0: [Head] --------------> [Node A] ------> [Node B] --> [Node C] ------> [Tail]  | - Lock-Free Hazard Handover |
+-------------------------------+-------------------------------------------+-------+-----------------------------+
                                |
                                v
               +----------------------------------+
               |    Descending MVCC Version Chain  |
               +----------------------------------+
               |  V_3 (ts: 300, del: INF)         |
               |       |                          |
               |       v                          |
               |  V_2 (ts: 200, del: 300)         |
               |       |                          |
               |       v                          |
               |  V_1 (ts: 100, del: 200)         |
               +----------------------------------+
```

---

## 1. Complete C++20 Header-Only Implementation (`mvcc_skiplist.hpp`)

```cpp
#pragma once

#include <atomic>
#include <cassert>
#include <cstddef>
#include <cstdint>
#include <cstring>
#include <functional>
#include <iostream>
#include <memory>
#include <new>
#include <optional>
#include <random>
#include <string>
#include <string_view>
#include <thread>
#include <type_traits>
#include <utility>
#include <vector>

namespace mvcc {

using tx_id_t = uint64_t;
inline constexpr tx_id_t TX_ID_MAX = std::numeric_limits<tx_id_t>::max();
inline constexpr size_t MAX_LEVEL = 32;
inline constexpr float SKIPLIST_P = 0.5f;

// ============================================================================
// 1. Safe Tagged Pointer (Fraser-Fomitchev Bit-Stealing)
// ============================================================================
template <typename T>
class TaggedPtr {
private:
    static constexpr uintptr_t MARK_MASK = 0x1ULL;
    static constexpr uintptr_t PTR_MASK = ~MARK_MASK;

    uintptr_t raw_{0};

public:
    constexpr TaggedPtr() noexcept : raw_(0) {}
    constexpr TaggedPtr(T* ptr, bool marked = false) noexcept
        : raw_(reinterpret_cast<uintptr_t>(ptr) | (marked ? MARK_MASK : 0)) {
        assert((reinterpret_cast<uintptr_t>(ptr) & MARK_MASK) == 0 && "Pointer must be at least 2-byte aligned");
    }
    explicit constexpr TaggedPtr(uintptr_t raw) noexcept : raw_(raw) {}

    [[nodiscard]] inline T* Get() const noexcept {
        return reinterpret_cast<T*>(raw_ & PTR_MASK);
    }

    [[nodiscard]] inline bool IsMarked() const noexcept {
        return (raw_ & MARK_MASK) != 0;
    }

    [[nodiscard]] inline uintptr_t Raw() const noexcept {
        return raw_;
    }

    [[nodiscard]] inline TaggedPtr WithMark(bool mark) const noexcept {
        return TaggedPtr(Get(), mark);
    }

    bool operator==(const TaggedPtr& other) const noexcept = default;
};

// ============================================================================
// 2. Dual-Epoch Safe Memory Reclamation (EBR) Engine
// ============================================================================
class EpochReclaimer {
public:
    struct RetiredNode {
        void* ptr{nullptr};
        void (*deleter)(void*){nullptr};
        RetiredNode* next{nullptr};
    };

    struct alignas(64) ThreadControlBlock {
        std::atomic<uint64_t> local_epoch{0};
        std::atomic<bool> is_active{false};
        std::atomic<ThreadControlBlock*> next{nullptr};

        // 3 Retirement rings corresponding to epoch % 3
        RetiredNode* retired[3]{nullptr, nullptr, nullptr};
        size_t retired_count{0};
        static constexpr size_t BATCH_THRESHOLD = 64;

        ~ThreadControlBlock() {
            for (auto& ring : retired) {
                RetiredNode* curr = ring;
                while (curr) {
                    RetiredNode* next_node = curr->next;
                    if (curr->deleter && curr->ptr) {
                        curr->deleter(curr->ptr);
                    }
                    delete curr;
                    curr = next_node;
                }
                ring = nullptr;
            }
        }
    };

private:
    std::atomic<uint64_t> global_epoch_{1};
    std::atomic<ThreadControlBlock*> thread_list_head_{nullptr};

    EpochReclaimer() = default;

public:
    static EpochReclaimer& Instance() {
        static EpochReclaimer reclaimer;
        return reclaimer;
    }

    ~EpochReclaimer() {
        ThreadControlBlock* curr = thread_list_head_.load(std::memory_order_relaxed);
        while (curr) {
            ThreadControlBlock* next = curr->next.load(std::memory_order_relaxed);
            delete curr;
            curr = next;
        }
    }

    ThreadControlBlock* RegisterThread() {
        auto* tcb = new ThreadControlBlock();
        ThreadControlBlock* old_head = thread_list_head_.load(std::memory_order_relaxed);
        do {
            tcb->next.store(old_head, std::memory_order_relaxed);
        } while (!thread_list_head_.compare_exchange_weak(
            old_head, tcb, std::memory_order_release, std::memory_order_relaxed));
        return tcb;
    }

    void EnterCritical(ThreadControlBlock* tcb) noexcept {
        uint64_t current_global = global_epoch_.load(std::memory_order_relaxed);
        tcb->local_epoch.store(current_global, std::memory_order_relaxed);
        tcb->is_active.store(true, std::memory_order_seq_cst);
    }

    void LeaveCritical(ThreadControlBlock* tcb) noexcept {
        tcb->is_active.store(false, std::memory_order_seq_cst);
    }

    template <typename T>
    void Retire(ThreadControlBlock* tcb, T* ptr) {
        if (!ptr) return;

        auto* rnode = new RetiredNode{
            .ptr = static_cast<void*>(ptr),
            .deleter = [](void* p) { delete static_cast<T*>(p); },
            .next = nullptr
        };

        uint64_t cur_epoch = global_epoch_.load(std::memory_order_relaxed);
        size_t ring_idx = cur_epoch % 3;
        rnode->next = tcb->retired[ring_idx];
        tcb->retired[ring_idx] = rnode;
        tcb->retired_count++;

        if (tcb->retired_count >= ThreadControlBlock::BATCH_THRESHOLD) {
            TryAdvanceEpochAndReclaim(tcb);
        }
    }

    void TryAdvanceEpochAndReclaim(ThreadControlBlock* tcb) {
        uint64_t cur_epoch = global_epoch_.load(std::memory_order_acquire);

        // Verify all active threads have caught up to the current epoch
        ThreadControlBlock* curr = thread_list_head_.load(std::memory_order_acquire);
        bool can_advance = true;
        while (curr) {
            if (curr->is_active.load(std::memory_order_acquire)) {
                if (curr->local_epoch.load(std::memory_order_acquire) < cur_epoch) {
                    can_advance = false;
                    break;
                }
            }
            curr = curr->next.load(std::memory_order_acquire);
        }

        if (can_advance) {
            if (global_epoch_.compare_exchange_strong(cur_epoch, cur_epoch + 1, 
                                                      std::memory_order_acq_rel)) {
                cur_epoch++;
            }
        }

        // Safe to reclaim nodes retired at or before (cur_epoch - 2)
        size_t reclaim_ring = (cur_epoch + 1) % 3;
        RetiredNode* to_free = tcb->retired[reclaim_ring];
        tcb->retired[reclaim_ring] = nullptr;

        while (to_free) {
            RetiredNode* next = to_free->next;
            if (to_free->deleter && to_free->ptr) {
                to_free->deleter(to_free->ptr);
                tcb->retired_count--;
            }
            delete to_free;
            to_free = next;
        }
    }

    [[nodiscard]] uint64_t GetCurrentEpoch() const noexcept {
        return global_epoch_.load(std::memory_order_acquire);
    }
};

struct EpochGuard {
    EpochReclaimer::ThreadControlBlock* tcb;
    explicit EpochGuard(EpochReclaimer::ThreadControlBlock* block) : tcb(block) {
        EpochReclaimer::Instance().EnterCritical(tcb);
    }
    ~EpochGuard() {
        EpochReclaimer::Instance().LeaveCritical(tcb);
    }
    EpochGuard(const EpochGuard&) = delete;
    EpochGuard& operator=(const EpochGuard&) = delete;
};

inline thread_local EpochReclaimer::ThreadControlBlock* tl_tcb = 
    EpochReclaimer::Instance().RegisterThread();

// ============================================================================
// 3. MVCC Version Chain Layout
// ============================================================================
template <typename Value>
struct VersionNode {
    tx_id_t created_tx_id;
    std::atomic<tx_id_t> deleted_tx_id;
    bool is_tombstone;
    Value value;
    std::atomic<VersionNode*> next_version;

    VersionNode(tx_id_t c_ts, tx_id_t d_ts, bool tombstone, Value val, VersionNode* next = nullptr)
        : created_tx_id(c_ts),
          deleted_tx_id(d_ts),
          is_tombstone(tombstone),
          value(std::move(val)),
          next_version(next) {}
};

// ============================================================================
// 4. Fraser-Fomitchev Lock-Free Skip-List Index Node
// ============================================================================
template <typename Key, typename Value>
struct IndexNode {
    Key key;
    size_t top_level;
    std::atomic<VersionNode<Value>*> version_head{nullptr};
    std::atomic<TaggedPtr<IndexNode<Key, Value>>> forward[MAX_LEVEL];

    IndexNode(Key k, size_t height)
        : key(std::move(k)), top_level(height) {
        for (size_t i = 0; i < MAX_LEVEL; ++i) {
            forward[i].store(TaggedPtr<IndexNode<Key, Value>>(nullptr, false), std::memory_order_relaxed);
        }
    }
};

// ============================================================================
// 5. MVCC Concurrent Skip-List Class
// ============================================================================
template <typename Key, typename Value, typename Compare = std::less<Key>>
class MVCCSkipList {
public:
    using Node = IndexNode<Key, Value>;
    using VNode = VersionNode<Value>;

private:
    Compare comp_;
    Node* head_;
    Node* tail_;
    std::atomic<size_t> max_active_level_{1};

    // Thread-local PRNG for tower height generation
    static size_t RandomLevel() {
        static thread_local std::mt19937_64 rng(std::random_device{}());
        static thread_local std::geometric_distribution<size_t> dist(1.0f - SKIPLIST_P);
        size_t lvl = dist(rng) + 1;
        return std::min(lvl, MAX_LEVEL);
    }

    bool KeyLess(const Key& a, const Key& b) const noexcept {
        return comp_(a, b);
    }

    bool KeyEqual(const Key& a, const Key& b) const noexcept {
        return !comp_(a, b) && !comp_(b, a);
    }

public:
    MVCCSkipList(Compare comp = Compare()) : comp_(comp) {
        head_ = new Node(Key{}, MAX_LEVEL);
        tail_ = new Node(Key{}, MAX_LEVEL);

        for (size_t i = 0; i < MAX_LEVEL; ++i) {
            head_->forward[i].store(TaggedPtr<Node>(tail_, false), std::memory_order_relaxed);
            tail_->forward[i].store(TaggedPtr<Node>(nullptr, false), std::memory_order_relaxed);
        }
    }

    ~MVCCSkipList() {
        Node* curr = head_->forward[0].load(std::memory_order_relaxed).Get();
        while (curr && curr != tail_) {
            Node* next = curr->forward[0].load(std::memory_order_relaxed).Get();

            // Clean up version chain
            VNode* vcurr = curr->version_head.load(std::memory_order_relaxed);
            while (vcurr) {
                VNode* vnext = vcurr->next_version.load(std::memory_order_relaxed);
                delete vcurr;
                vcurr = vnext;
            }
            delete curr;
            curr = next;
        }
        delete head_;
        delete tail_;
    }

    MVCCSkipList(const MVCCSkipList&) = delete;
    MVCCSkipList& operator=(const MVCCSkipList&) = delete;

private:
    // ========================================================================
    // Fraser-Fomitchev Search & Physical Deletion Helper
    // ========================================================================
    bool SearchTower(const Key& key,
                     Node* left_nodes[MAX_LEVEL],
                     Node* right_nodes[MAX_LEVEL]) const {
    retry:
        Node* t_left = head_;
        for (int i = static_cast<int>(MAX_LEVEL - 1); i >= 0; --i) {
            TaggedPtr<Node> t_left_tagged = t_left->forward[i].load(std::memory_order_acquire);
            Node* t_right = t_left_tagged.Get();

            while (true) {
                if (!t_right || t_right == tail_) {
                    break;
                }

                TaggedPtr<Node> t_right_tagged = t_right->forward[i].load(std::memory_order_acquire);

                // Physical unlinking of logically deleted (marked) nodes
                while (t_right_tagged.IsMarked()) {
                    TaggedPtr<Node> unmarked_left = TaggedPtr<Node>(t_right, false);
                    TaggedPtr<Node> new_target = TaggedPtr<Node>(t_right_tagged.Get(), false);

                    if (!t_left->forward[i].compare_exchange_strong(
                            unmarked_left, new_target,
                            std::memory_order_acq_rel, std::memory_order_acquire)) {
                        goto retry;
                    }

                    // Node unlinked at level 0 is retired safely to EBR
                    if (i == 0) {
                        EpochReclaimer::Instance().Retire(tl_tcb, t_right);
                    }

                    t_right = t_right_tagged.Get();
                    if (!t_right || t_right == tail_) break;
                    t_right_tagged = t_right->forward[i].load(std::memory_order_acquire);
                }

                if (!t_right || t_right == tail_) {
                    break;
                }

                if (KeyLess(t_right->key, key)) {
                    t_left = t_right;
                    t_right = t_right_tagged.Get();
                } else {
                    break;
                }
            }

            left_nodes[i] = t_left;
            right_nodes[i] = t_right;
        }

        return (right_nodes[0] != tail_ && right_nodes[0] != nullptr && 
                KeyEqual(right_nodes[0]->key, key));
    }

    // Unlinks all levels of a marked node
    void PhysicallyUnlink(Node* node) {
        Node* left[MAX_LEVEL];
        Node* right[MAX_LEVEL];
        SearchTower(node->key, left, right);
    }

public:
    // ========================================================================
    // MVCC Operations: Insert, Delete, Read, Seek
    // ========================================================================

    bool Insert(const Key& key, const Value& val, tx_id_t commit_ts) {
        EpochGuard guard(tl_tcb);
        Node* left[MAX_LEVEL];
        Node* right[MAX_LEVEL];

        Node* target_node = nullptr;

        while (true) {
            bool found = SearchTower(key, left, right);
            if (found) {
                target_node = right[0];
                break;
            }

            // Key does not exist in skip list: insert index node
            size_t height = RandomLevel();
            auto* new_node = new Node(key, height);

            for (size_t i = 0; i < height; ++i) {
                new_node->forward[i].store(TaggedPtr<Node>(right[i], false), std::memory_order_relaxed);
            }

            // Atomic insertion at Level 0
            TaggedPtr<Node> expected(right[0], false);
            TaggedPtr<Node> desired(new_node, false);
            if (!left[0]->forward[0].compare_exchange_strong(
                    expected, desired, std::memory_order_release, std::memory_order_acquire)) {
                delete new_node;
                continue; // CAS race on level 0, retry search
            }

            // Link higher levels
            for (size_t i = 1; i < height; ++i) {
                while (true) {
                    TaggedPtr<Node> exp_right(right[i], false);
                    TaggedPtr<Node> des_new(new_node, false);
                    if (left[i]->forward[i].compare_exchange_strong(
                            exp_right, des_new, std::memory_order_release, std::memory_order_acquire)) {
                        break;
                    }
                    // Re-search to find new left and right at level i
                    SearchTower(key, left, right);
                    new_node->forward[i].store(TaggedPtr<Node>(right[i], false), std::memory_order_relaxed);
                }
            }

            target_node = new_node;
            break;
        }

        // Install new MVCC version in descending timestamp order at version chain head
        auto* new_vnode = new VNode(commit_ts, TX_ID_MAX, false, val);
        while (true) {
            VNode* cur_vhead = target_node->version_head.load(std::memory_order_acquire);
            if (cur_vhead && cur_vhead->created_tx_id >= commit_ts) {
                // Duplicate/Out-of-order write conflict
                delete new_vnode;
                return false;
            }

            new_vnode->next_version.store(cur_vhead, std::memory_order_relaxed);
            if (target_node->version_head.compare_exchange_weak(
                    cur_vhead, new_vnode, std::memory_order_release, std::memory_order_acquire)) {
                // Successfully prepended: set deleted_tx_id on previous live version
                if (cur_vhead) {
                    tx_id_t exp_del = TX_ID_MAX;
                    cur_vhead->deleted_tx_id.compare_exchange_strong(
                        exp_del, commit_ts, std::memory_order_release, std::memory_order_relaxed);
                }
                return true;
            }
        }
    }

    bool Delete(const Key& key, tx_id_t commit_ts) {
        EpochGuard guard(tl_tcb);
        Node* left[MAX_LEVEL];
        Node* right[MAX_LEVEL];

        if (!SearchTower(key, left, right)) {
            return false; // Key not indexed
        }

        Node* target_node = right[0];

        // Insert a tombstone version
        auto* tombstone = new VNode(commit_ts, TX_ID_MAX, true, Value{});
        while (true) {
            VNode* cur_vhead = target_node->version_head.load(std::memory_order_acquire);
            if (cur_vhead && cur_vhead->created_tx_id >= commit_ts) {
                delete tombstone;
                return false;
            }

            tombstone->next_version.store(cur_vhead, std::memory_order_relaxed);
            if (target_node->version_head.compare_exchange_weak(
                    cur_vhead, tombstone, std::memory_order_release, std::memory_order_acquire)) {
                if (cur_vhead) {
                    tx_id_t exp_del = TX_ID_MAX;
                    cur_vhead->deleted_tx_id.compare_exchange_strong(
                        exp_del, commit_ts, std::memory_order_release, std::memory_order_relaxed);
                }
                return true;
            }
        }
    }

    [[nodiscard]] std::optional<Value> Read(const Key& key, tx_id_t read_ts) const {
        EpochGuard guard(tl_tcb);
        Node* left[MAX_LEVEL];
        Node* right[MAX_LEVEL];

        if (!SearchTower(key, left, right)) {
            return std::nullopt;
        }

        Node* target_node = right[0];
        VNode* vcurr = target_node->version_head.load(std::memory_order_acquire);

        // Visibility Rule: created_tx_id <= read_ts < deleted_tx_id
        while (vcurr) {
            tx_id_t c_ts = vcurr->created_tx_id;
            tx_id_t d_ts = vcurr->deleted_tx_id.load(std::memory_order_acquire);

            if (c_ts <= read_ts && read_ts < d_ts) {
                if (vcurr->is_tombstone) {
                    return std::nullopt; // Logically deleted at read_ts
                }
                return vcurr->value;
            }
            vcurr = vcurr->next_version.load(std::memory_order_acquire);
        }

        return std::nullopt;
    }

    // ========================================================================
    // Snapshot-Isolated Range Iterator
    // ========================================================================
    class MVCCIterator {
    private:
        const MVCCSkipList* list_;
        Node* current_node_;
        tx_id_t read_ts_;
        std::optional<std::pair<Key, Value>> current_kv_;
        EpochReclaimer::ThreadControlBlock* tcb_;

        void AdvanceToVisible() {
            while (current_node_ && current_node_ != list_->tail_) {
                // If current node is marked, advance
                if (current_node_->forward[0].load(std::memory_order_acquire).IsMarked()) {
                    current_node_ = current_node_->forward[0].load(std::memory_order_acquire).Get();
                    continue;
                }

                VNode* vcurr = current_node_->version_head.load(std::memory_order_acquire);
                while (vcurr) {
                    tx_id_t c_ts = vcurr->created_tx_id;
                    tx_id_t d_ts = vcurr->deleted_tx_id.load(std::memory_order_acquire);

                    if (c_ts <= read_ts_ && read_ts_ < d_ts) {
                        if (!vcurr->is_tombstone) {
                            current_kv_ = std::make_pair(current_node_->key, vcurr->value);
                            return;
                        }
                        break; // Tombstone is visible -> key is deleted
                    }
                    vcurr = vcurr->next_version.load(std::memory_order_acquire);
                }

                current_node_ = current_node_->forward[0].load(std::memory_order_acquire).Get();
            }
            current_kv_ = std::nullopt;
        }

    public:
        MVCCIterator(const MVCCSkipList* list, Node* start_node, tx_id_t read_ts, 
                     EpochReclaimer::ThreadControlBlock* tcb)
            : list_(list), current_node_(start_node), read_ts_(read_ts), tcb_(tcb) {
            EpochReclaimer::Instance().EnterCritical(tcb_);
            AdvanceToVisible();
        }

        ~MVCCIterator() {
            if (tcb_) {
                EpochReclaimer::Instance().LeaveCritical(tcb_);
            }
        }

        MVCCIterator(MVCCIterator&& other) noexcept
            : list_(other.list_), current_node_(other.current_node_),
              read_ts_(other.read_ts_), current_kv_(std::move(other.current_kv_)),
              tcb_(other.tcb_) {
            other.tcb_ = nullptr;
        }

        MVCCIterator& operator=(MVCCIterator&& other) noexcept {
            if (this != &other) {
                if (tcb_) EpochReclaimer::Instance().LeaveCritical(tcb_);
                list_ = other.list_;
                current_node_ = other.current_node_;
                read_ts_ = other.read_ts_;
                current_kv_ = std::move(other.current_kv_);
                tcb_ = other.tcb_;
                other.tcb_ = nullptr;
            }
            return *this;
        }

        MVCCIterator(const MVCCIterator&) = delete;
        MVCCIterator& operator=(const MVCCIterator&) = delete;

        [[nodiscard]] bool HasValue() const noexcept {
            return current_kv_.has_value();
        }

        [[nodiscard]] const std::pair<Key, Value>& operator*() const noexcept {
            return *current_kv_;
        }

        [[nodiscard]] const std::pair<Key, Value>* operator->() const noexcept {
            return &(*current_kv_);
        }

        void Next() {
            if (current_node_ && current_node_ != list_->tail_) {
                current_node_ = current_node_->forward[0].load(std::memory_order_acquire).Get();
                AdvanceToVisible();
            } else {
                current_kv_ = std::nullopt;
            }
        }
    };

    [[nodiscard]] MVCCIterator Seek(const Key& min_key, tx_id_t read_ts) const {
        Node* left[MAX_LEVEL];
        Node* right[MAX_LEVEL];
        SearchTower(min_key, left, right);
        return MVCCIterator(this, right[0], read_ts, tl_tcb);
    }

    // ========================================================================
    // 6. Asynchronous Multi-Version Garbage Collector & Compactor
    // ========================================================================
    void CollectGarbage(tx_id_t global_min_active_ts) {
        EpochGuard guard(tl_tcb);
        Node* prev = head_;
        TaggedPtr<Node> curr_tagged = head_->forward[0].load(std::memory_order_acquire);
        Node* curr = curr_tagged.Get();

        while (curr && curr != tail_) {
            TaggedPtr<Node> next_tagged = curr->forward[0].load(std::memory_order_acquire);
            if (next_tagged.IsMarked()) {
                // Node already being unlinked
                curr = next_tagged.Get();
                continue;
            }

            // Step A: Compact Version Chain
            VNode* vcurr = curr->version_head.load(std::memory_order_acquire);
            VNode* vprev = nullptr;

            while (vcurr) {
                VNode* vnext = vcurr->next_version.load(std::memory_order_acquire);
                tx_id_t d_ts = vcurr->deleted_tx_id.load(std::memory_order_acquire);

                // Prune dead versions whose lifespan ended strictly before min active snapshot
                if (d_ts < global_min_active_ts) {
                    if (vprev == nullptr) {
                        // Attempt to swing version_head to vnext
                        if (curr->version_head.compare_exchange_strong(
                                vcurr, vnext, std::memory_order_acq_rel, std::memory_order_acquire)) {
                            EpochReclaimer::Instance().Retire(tl_tcb, vcurr);
                            vcurr = vnext;
                            continue;
                        }
                    } else {
                        // Atomic splice in internal version chain
                        if (vprev->next_version.compare_exchange_strong(
                                vcurr, vnext, std::memory_order_acq_rel, std::memory_order_acquire)) {
                            EpochReclaimer::Instance().Retire(tl_tcb, vcurr);
                            vcurr = vnext;
                            continue;
                        }
                    }
                }
                vprev = vcurr;
                vcurr = vnext;
            }

            // Step B: Index Tower Compaction (Dead Key Purge)
            VNode* head_vnode = curr->version_head.load(std::memory_order_acquire);
            if (!head_vnode || (head_vnode->is_tombstone && 
                head_vnode->deleted_tx_id.load(std::memory_order_acquire) < global_min_active_ts &&
                head_vnode->next_version.load(std::memory_order_acquire) == nullptr)) {

                // Key is completely dead across all active snapshots: logically mark tower
                bool mark_success = true;
                for (int i = static_cast<int>(curr->top_level - 1); i >= 0; --i) {
                    TaggedPtr<Node> expected_fwd = curr->forward[i].load(std::memory_order_acquire);
                    while (!expected_fwd.IsMarked()) {
                        TaggedPtr<Node> marked_fwd = expected_fwd.WithMark(true);
                        if (curr->forward[i].compare_exchange_weak(
                                expected_fwd, marked_fwd, 
                                std::memory_order_acq_rel, std::memory_order_acquire)) {
                            break;
                        }
                    }
                }

                // Trigger physical unlinking
                PhysicallyUnlink(curr);
            }

            curr = curr->forward[0].load(std::memory_order_acquire).Get();
        }
    }
};

} // namespace mvcc
