namespace mvcc {

using tx_id_t = uint64_t;
inline constexpr tx_id_t TX_ID_MAX = std::numeric_limits<tx_id_t>::max();
inline constexpr size_t MAX_HEIGHT = 32;
inline constexpr double SKIPLIST_P = 0.5;

// ============================================================================
// 1. Bit-Marked Pointer Utilities (Fraser-Fomitchev Lock-Free Primitives)
// ============================================================================
template <typename T>
class MarkedPtr {
private:
    uintptr_t ptr_val_;

public:
    constexpr MarkedPtr() noexcept : ptr_val_(0) {}
    constexpr MarkedPtr(T* ptr, bool marked = false) noexcept
        : ptr_val_(reinterpret_cast<uintptr_t>(ptr) | (marked ? 1ULL : 0ULL)) {}
    constexpr explicit MarkedPtr(uintptr_t val) noexcept : ptr_val_(val) {}

    [[nodiscard]] inline T* get() const noexcept {
        return reinterpret_cast<T*>(ptr_val_ & ~static_cast<uintptr_t>(1));
    }

    [[nodiscard]] inline bool is_marked() const noexcept {
        return (ptr_val_ & 1ULL) != 0;
    }

    [[nodiscard]] inline uintptr_t raw() const noexcept {
        return ptr_val_;
    }

    [[nodiscard]] inline MarkedPtr<T> with_mark(bool mark) const noexcept {
        return MarkedPtr<T>(get(), mark);
    }

    bool operator==(const MarkedPtr& other) const noexcept { return ptr_val_ == other.ptr_val_; }
    bool operator!=(const MarkedPtr& other) const noexcept { return ptr_val_ != other.ptr_val_; }
};

// ============================================================================
// 2. Safe Memory Reclamation: Decentralized Epoch-Based Reclamation (EBR)
// ============================================================================
class EpochReclaimer {
public:
    static constexpr size_t RETIRE_THRESHOLD = 64;

    struct RetireNode {
        void* ptr;
        void (*deleter)(void*);
        uint64_t epoch;
        RetireNode* next;
    };

    struct alignas(64) ThreadEpochState {
        std::atomic<uint64_t> local_epoch{0};
        std::atomic<bool> active{false};
        RetireNode* retire_head{nullptr};
        size_t retire_count{0};
        ThreadEpochState* next{nullptr};
    };

private:
    std::atomic<uint64_t> global_epoch_{1};
    std::atomic<ThreadEpochState*> thread_states_{nullptr};

    EpochReclaimer() = default;

public:
    static EpochReclaimer& Instance() {
        static EpochReclaimer instance;
        return instance;
    }

    ThreadEpochState* RegisterThread() {
        auto* state = new ThreadEpochState();
        ThreadEpochState* old_head = thread_states_.load(std::memory_order_relaxed);
        do {
            state->next = old_head;
        } while (!thread_states_.compare_exchange_weak(
            old_head, state, std::memory_order_release, std::memory_order_relaxed));
        return state;
    }

    void Enter(ThreadEpochState* state) noexcept {
        state->local_epoch.store(global_epoch_.load(std::memory_order_relaxed), std::memory_order_relaxed);
        state->active.store(true, std::memory_order_release);
    }

    void Leave(ThreadEpochState* state) noexcept {
        state->active.store(false, std::memory_order_release);
    }

    template <typename T>
    void Retire(ThreadEpochState* state, T* obj) {
        if (!obj) return;
        auto* node = new RetireNode{
            obj,
            [](void* p) { delete static_cast<T*>(p); },
            global_epoch_.load(std::memory_order_relaxed),
            state->retire_head
        };
        state->retire_head = node;
        state->retire_count++;

        if (state->retire_count >= RETIRE_THRESHOLD) {
            TryAdvanceAndReclaim(state);
        }
    }

    void TryAdvanceAndReclaim(ThreadEpochState* state) {
        uint64_t g_epoch = global_epoch_.load(std::memory_order_relaxed);
        uint64_t min_epoch = g_epoch;

        ThreadEpochState* curr = thread_states_.load(std::memory_order_acquire);
        bool can_advance = true;

        while (curr) {
            if (curr->active.load(std::memory_order_acquire)) {
                uint64_t t_epoch = curr->local_epoch.load(std::memory_order_relaxed);
                if (t_epoch < min_epoch) {
                    min_epoch = t_epoch;
                }
                if (t_epoch < g_epoch) {
                    can_advance = false;
                }
            }
            curr = curr->next;
        }

        if (can_advance) {
            global_epoch_.fetch_add(1, std::memory_order_acq_rel);
        }

        // Reclaim memory older than min_epoch
        RetireNode* prev = nullptr;
        RetireNode* node = state->retire_head;
        while (node) {
            if (node->epoch < min_epoch) {
                node->deleter(node->ptr);
                RetireNode* to_del = node;
                if (prev) {
                    prev->next = node->next;
                    node = node->next;
                } else {
                    state->retire_head = node->next;
                    node = state->retire_head;
                }
                delete to_del;
                state->retire_count--;
            } else {
                prev = node;
                node = node->next;
            }
        }
    }
};

// Thread-local epoch guard RAII
struct EpochGuard {
    EpochReclaimer::ThreadEpochState* state;
    explicit EpochGuard(EpochReclaimer::ThreadEpochState* s) : state(s) {
        EpochReclaimer::Instance().Enter(state);
    }
    ~EpochGuard() {
        EpochReclaimer::Instance().Leave(state);
    }
};

