// 3. MVCC Version & Skip-List Node Layout
// ============================================================================
template <typename Value>
struct VersionNode {
    tx_id_t created_tx_id;
    std::atomic<tx_id_t> deleted_tx_id;
    std::optional<Value> value; // std::nullopt represents a tombstone
    std::atomic<VersionNode<Value>*> next_version;

    VersionNode(tx_id_t created_ts, std::optional<Value> val, VersionNode<Value>* next = nullptr)
        : created_tx_id(created_ts),
          deleted_tx_id(TX_ID_MAX),
          value(std::move(val)),
          next_version(next) {}
};

template <typename Key, typename Value>
struct IndexNode {
    Key key;
    size_t height;
    std::atomic<VersionNode<Value>*> version_head;
    std::atomic<MarkedPtr<IndexNode<Key, Value>>> next[MAX_HEIGHT];

    IndexNode(Key k, size_t h, VersionNode<Value>* v_head = nullptr)
        : key(std::move(k)), height(h), version_head(v_head) {
        for (size_t i = 0; i < MAX_HEIGHT; ++i) {
            next[i].store(MarkedPtr<IndexNode<Key, Value>>(nullptr), std::memory_order_relaxed);
        }
    }
};

// ============================================================================
// 4. MVCC Lock-Free Skip-List Class
// ============================================================================
template <typename Key, typename Value, typename Compare = std::less<Key>>
class MVCCSkipList {
public:
    using Node = IndexNode<Key, Value>;
    using Version = VersionNode<Value>;

private:
    Compare comp_;
    Node* head_;
    inline static thread_local EpochReclaimer::ThreadEpochState* tls_epoch_state = nullptr;

    EpochReclaimer::ThreadEpochState* GetTLSState() {
        if (!tls_epoch_state) {
            tls_epoch_state = EpochReclaimer::Instance().RegisterThread();
        }
        return tls_epoch_state;
    }

    size_t GenerateRandomHeight() noexcept {
        static thread_local std::mt19937_64 rng(std::random_device{}());
        static thread_local std::uniform_real_distribution<double> dist(0.0, 1.0);
        size_t h = 1;
        while (h < MAX_HEIGHT && dist(rng) < SKIPLIST_P) {
            h++;
        }
        return h;
    }

    // Helper: Lock-free search with Fraser-Fomitchev physical deletion help
    bool SearchWithHelp(const Key& key,
                        std::array<Node*, MAX_HEIGHT>& preds,
                        std::array<Node*, MAX_HEIGHT>& succs) {
    retry:
        Node* pred = head_;
        for (int l = static_cast<int>(MAX_HEIGHT) - 1; l >= 0; --l) {
            MarkedPtr<Node> curr = pred->next[l].load(std::memory_order_acquire);
            while (true) {
                if (!curr.get()) {
                    break;
                }
                MarkedPtr<Node> succ = curr.get()->next[l].load(std::memory_order_acquire);
                while (succ.is_marked()) {
                    // Help physically unlink marked node curr.get()
                    MarkedPtr<Node> expected = curr;
                    MarkedPtr<Node> desired(succ.get(), false);
                    if (!pred->next[l].compare_exchange_weak(
                            expected, desired, std::memory_order_acq_rel, std::memory_order_acquire)) {
                        goto retry;
                    }
                    curr = desired;
                    if (!curr.get()) break;
                    succ = curr.get()->next[l].load(std::memory_order_acquire);
                }

                if (!curr.get()) break;

                if (comp_(curr.get()->key, key)) {
                    pred = curr.get();
                    curr = succ;
                } else {
                    break;
                }
            }
            preds[l] = pred;
            succs[l] = curr.get();
        }
        return (succs[0] && !comp_(key, succs[0]->key) && !comp_(succs[0]->key, key));
    }

public:
    explicit MVCCSkipList(Compare comp = Compare())
        : comp_(comp), head_(new Node(Key{}, MAX_HEIGHT)) {}

    ~MVCCSkipList() {
        Node* curr = head_->next[0].load(std::memory_order_relaxed).get();
        while (curr) {
            Node* next_node = curr->next[0].load(std::memory_order_relaxed).get();
            Version* v_curr = curr->version_head.load(std::memory_order_relaxed);
            while (v_curr) {
                Version* v_next = v_curr->next_version.load(std::memory_order_relaxed);
                delete v_curr;
                v_curr = v_next;
            }
            delete curr;
            curr = next_node;
        }
        delete head_;
    }

    // Disallow copies
    MVCCSkipList(const MVCCSkipList&) = delete;
    MVCCSkipList& operator=(const MVCCSkipList&) = delete;

    // ------------------------------------------------------------------------
    // Insertion & Upsert
    // ------------------------------------------------------------------------
    bool Insert(const Key& key, const Value& val, tx_id_t commit_ts) {
        auto* state = GetTLSState();
        EpochGuard guard(state);

        std::array<Node*, MAX_HEIGHT> preds{};
        std::array<Node*, MAX_HEIGHT> succs{};

        while (true) {
            if (SearchWithHelp(key, preds, succs)) {
                // Key exists: atomically append new version to existing index node
                Node* target = succs[0];
                Version* old_head = target->version_head.load(std::memory_order_acquire);

                // Check for write conflict on the same timestamp
                if (old_head && old_head->created_tx_id >= commit_ts) {
                    return false;
                }

                auto* new_version = new Version(commit_ts, val, old_head);
                if (target->version_head.compare_exchange_weak(
                        old_head, new_version, std::memory_order_release, std::memory_order_acquire)) {
                    // Mark old head as deleted by this commit_ts
                    if (old_head) {
                        tx_id_t exp_del = TX_ID_MAX;
                        old_head->deleted_tx_id.compare_exchange_strong(
                            exp_del, commit_ts, std::memory_order_release, std::memory_order_relaxed);
                    }
                    return true;
                }
                delete new_version;
                continue; // Retry insertion on version CAS race
            }

            // Key does not exist: create a new IndexNode
            size_t height = GenerateRandomHeight();
            auto* initial_version = new Version(commit_ts, val);
            auto* new_node = new Node(key, height, initial_version);

            for (size_t i = 0; i < height; ++i) {
                new_node->next[i].store(MarkedPtr<Node>(succs[i], false), std::memory_order_relaxed);
            }

            // Linearization Point: bottom-level CAS
            MarkedPtr<Node> expected(succs[0], false);
            MarkedPtr<Node> desired(new_node, false);
            if (!preds[0]->next[0].compare_exchange_weak(
                    expected, desired, std::memory_order_acq_rel, std::memory_order_acquire)) {
                delete initial_version;
                delete new_node;
                continue; // Retry
            }

            // Link higher levels
            for (size_t i = 1; i < height; ++i) {
                while (true) {
                    MarkedPtr<Node> exp_succ(succs[i], false);
                    new_node->next[i].store(exp_succ, std::memory_order_relaxed);
                    if (preds[i]->next[i].compare_exchange_weak(
                            exp_succ, desired, std::memory_order_acq_rel, std::memory_order_acquire)) {
                        break; // Level successfully linked
                    }
                    // Re-search to find new predecessors and successors for this level
                    SearchWithHelp(key, preds, succs);
                }
            }
            return true;
        }
    }

    // ------------------------------------------------------------------------
    // Logical Deletion (MVCC Tombstone)
    // ------------------------------------------------------------------------
    bool Delete(const Key& key, tx_id_t commit_ts) {
        auto* state = GetTLSState();
        EpochGuard guard(state);

        std::array<Node*, MAX_HEIGHT> preds{};
        std::array<Node*, MAX_HEIGHT> succs{};

        while (true) {
            if (!SearchWithHelp(key, preds, succs)) {
                return false; // Key does not exist
            }

            Node* target = succs[0];
            Version* old_head = target->version_head.load(std::memory_order_acquire);

            if (!old_head || !old_head->value.has_value()) {
                return false; // Already logically deleted
            }
            if (old_head->created_tx_id >= commit_ts) {
                return false; // Concurrent newer transaction detected
            }

            // Tombstone version (nullopt)
            auto* tombstone = new Version(commit_ts, std::nullopt, old_head);
            if (target->version_head.compare_exchange_weak(
                    old_head, tombstone, std::memory_order_release, std::memory_order_acquire)) {
                tx_id_t exp_del = TX_ID_MAX;
                old_head->deleted_tx_id.compare_exchange_strong(
                    exp_del, commit_ts, std::memory_order_release, std::memory_order_relaxed);
                return true;
            }
            delete tombstone;
        }
    }

    // ------------------------------------------------------------------------
    // Point Lookup (Snapshot Isolated Read)
    // ------------------------------------------------------------------------
    std::optional<Value> Read(const Key& key, tx_id_t read_ts) {
        auto* state = GetTLSState();
        EpochGuard guard(state);

        Node* pred = head_;
        for (int l = static_cast<int>(MAX_HEIGHT) - 1; l >= 0; --l) {
            MarkedPtr<Node> curr = pred->next[l].load(std::memory_order_acquire);
            while (curr.get()) {
                if (curr.is_marked()) {
                    curr = curr.get()->next[l].load(std::memory_order_acquire);
                    continue;
                }
                if (comp_(curr.get()->key, key)) {
                    pred = curr.get();
                    curr = pred->next[l].load(std::memory_order_acquire);
                } else {
                    break;
                }
            }
        }

        MarkedPtr<Node> curr = pred->next[0].load(std::memory_order_acquire);
        while (curr.get() && curr.is_marked()) {
            curr = curr.get()->next[0].load(std::memory_order_acquire);
        }

        if (curr.get() && !comp_(key, curr.get()->key) && !comp_(curr.get()->key, key)) {
            // Traverse MVCC version chain
            Version* v = curr.get()->version_head.load(std::memory_order_acquire);
            while (v) {
                tx_id_t c_ts = v->created_tx_id;
                tx_id_t d_ts = v->deleted_tx_id.load(std::memory_order_acquire);
                if (c_ts <= read_ts && read_ts < d_ts) {
                    return v->value; // May be std::nullopt if tombstone
                }
                v = v->next_version.load(std::memory_order_acquire);
            }
        }
        return std::nullopt;
    }

    // ------------------------------------------------------------------------
    // Snapshot Iterator
    // ------------------------------------------------------------------------
    class MVCCIterator {
    private:
        MVCCSkipList* list_;
        Node* curr_node_;
        tx_id_t read_ts_;
        std::optional<Value> curr_val_;

        void AdvanceToNextValid() {
            while (curr_node_) {
                if (!curr_node_->next[0].load(std::memory_order_relaxed).is_marked()) {
                    // Check version chain
                    Version* v = curr_node_->version_head.load(std::memory_order_acquire);
                    while (v) {
                        if (v->created_tx_id <= read_ts_ && read_ts_ < v->deleted_tx_id.load(std::memory_order_acquire)) {
                            if (v->value.has_value()) {
                                curr_val_ = v->value;
                                return;
                            }
                            break; // Tombstone active at read_ts
                        }
                        v = v->next_version.load(std::memory_order_acquire);
                    }
                }
                MarkedPtr<Node> nxt = curr_node_->next[0].load(std::memory_order_acquire);
                curr_node_ = nxt.get();
            }
            curr_val_ = std::nullopt;
        }

    public:
        MVCCIterator(MVCCSkipList* list, Node* start_node, tx_id_t read_ts)
            : list_(list), curr_node_(start_node), read_ts_(read_ts) {
            AdvanceToNextValid();
        }

        [[nodiscard]] bool HasValue() const noexcept {
            return curr_node_ != nullptr && curr_val_.has_value();
        }

        [[nodiscard]] const Key& GetKey() const {
            return curr_node_->key;
        }

        [[nodiscard]] const Value& GetValue() const {
            return *curr_val_;
        }

        void Next() {
            if (curr_node_) {
                MarkedPtr<Node> nxt = curr_node_->next[0].load(std::memory_order_acquire);
                curr_node_ = nxt.get();
                AdvanceToNextValid();
            }
        }
    };

    MVCCIterator Seek(const Key& min_key, tx_id_t read_ts) {
        auto* state = GetTLSState();
        EpochGuard guard(state);

        std::array<Node*, MAX_HEIGHT> preds{};
        std::array<Node*, MAX_HEIGHT> succs{};
        SearchWithHelp(min_key, preds, succs);

        Node* start = succs[0];
        return MVCCIterator(this, start, read_ts);
    }

    // ------------------------------------------------------------------------
    // Asynchronous Garbage Collection & Compaction
    // ------------------------------------------------------------------------
    void CollectGarbage(tx_id_t global_min_active_ts) {
        auto* state = GetTLSState();
        EpochGuard guard(state);

        Node* prev = head_;
        MarkedPtr<Node> curr_ptr = head_->next[0].load(std::memory_order_acquire);

        while (curr_ptr.get()) {
            Node* curr = curr_ptr.get();
            MarkedPtr<Node> succ = curr->next[0].load(std::memory_order_acquire);

            if (succ.is_marked()) {
                // Already marked for deletion; help physical unlink at level 0
                MarkedPtr<Node> exp(curr, false);
                MarkedPtr<Node> desired(succ.get(), false);
                if (prev->next[0].compare_exchange_strong(
                        exp, desired, std::memory_order_acq_rel, std::memory_order_acquire)) {
                    EpochReclaimer::Instance().Retire(state, curr);
                }
                curr_ptr = succ.get();
                continue;
            }

            // 1. Compact outdated versions in version chain
            Version* v_prev = nullptr;
            Version* v_curr = curr->version_head.load(std::memory_order_acquire);
            bool all_tombstones = true;

            while (v_curr) {
                Version* v_next = v_curr->next_version.load(std::memory_order_acquire);
                tx_id_t d_ts = v_curr->deleted_tx_id.load(std::memory_order_acquire);

                if (d_ts < global_min_active_ts) {
                    // Version invisible to all present and future transactions
                    if (v_prev) {
                        v_prev->next_version.store(v_next, std::memory_order_release);
                    } else {
                        curr->version_head.store(v_next, std::memory_order_release);
                    }
                    EpochReclaimer::Instance().Retire(state, v_curr);
                } else {
                    if (v_curr->value.has_value()) {
                        all_tombstones = false;
                    }
                    v_prev = v_curr;
                }
                v_curr = v_next;
            }

            // 2. If entire history is dead/tombstones older than active ts, mark index node
            Version* active_head = curr->version_head.load(std::memory_order_acquire);
            if (active_head == nullptr || (all_tombstones && active_head->created_tx_id < global_min_active_ts)) {
                // Logically mark all levels from top down
                for (int l = static_cast<int>(curr->height) - 1; l >= 0; --l) {
                    MarkedPtr<Node> cur_next = curr->next[l].load(std::memory_order_acquire);
                    while (!cur_next.is_marked()) {
                        MarkedPtr<Node> marked(cur_next.get(), true);
                        if (curr->next[l].compare_exchange_weak(
                                cur_next, marked, std::memory_order_acq_rel, std::memory_order_acquire)) {
                            break;
                        }
                    }
                }
            } else {
                prev = curr;
            }
            curr_ptr = succ.get();
        }
    }
};

} // namespace mvcc
```

---

### 3. Linearizability & Correctness Proof Outline

#### A. Linearization Points (LP)

| Operation | Condition | Linearization Point | Rationale |
| :--- | :--- | :--- | :--- |
| **`Insert(Key, Val, commit_ts)`** | Key does not exist | Atomic `compare_exchange_weak` on `preds[0]->next[0]` | Publishes the node to level 0. Any concurrent reader traversing level 0 will now observe this node. |
| | Key exists | Atomic `compare_exchange_weak` on `target->version_head` | Publishes the new version node at the head of the version chain with acquire-release fence. |
| **`Delete(Key, commit_ts)`** | Key exists & live | Atomic `compare_exchange_weak` on `target->version_head` | Installs tombstone (`value = nullopt`) version, atomically updated. |
| **`Read(Key, read_ts)`** | Key found/not found | Atomic load of `version_head` or `deleted_tx_id` satisfying $created \le read\_ts < deleted$ | Immutable version snapshot view; acquire fence guarantees visibility of payload. |
| **`Seek(Key, read_ts)`** | Range Scan | Atomic load of `next[0]` pointers for each step + version load | Each node access linearizes at its respective level-0 pointer dereference within the read snapshot epoch. |
| **`CollectGarbage(min_ts)`** | Version unlinking | Atomic store/CAS splicing `v_prev->next_version` | Safe because versions with $deleted\_ts < min\_ts$ are permanently unreachable by live readers. |

#### B. Safe Memory Reclamation (EBR) & ABA Freedom
1. **Dangling Pointer Freedom**: An index node or version node $N$ retired at global epoch $e$ is only physically freed when $\forall \text{ active threads } T$, $\text{epoch}(T) > e$. A reader enters epoch $e_r \ge e$ before acquiring pointers. Therefore, no thread can access $N$ after it is deallocated.
2. **ABA Mitigation**: Pointer marks (`MarkedPtr`, LSB 1) ensure that once a node is logically unlinked, no thread can swing its forward pointers. Physical unlinking uses `compare_exchange` against unmarked pointers, preventing obsolete predecessor swings.

---

### 4. Microbenchmark & Stress Harness

Save this file as `benchmark_main.cpp`. Compile with:
