//! High-Throughput Lock-Free Epoch-Based MVCC Storage Engine
//! with Asynchronous O_DIRECT Group-Commit WAL Pipeline.

use std::alloc::{alloc_zeroed, dealloc, Layout};
use std::cell::UnsafeCell;
use std::collections::HashMap;
use std::fs::{File, OpenOptions};
use std::io::{Read, Seek, SeekFrom, Write};
use std::path::{Path, PathBuf};
use std::ptr::{self, NonNull};
use std::sync::atomic::{
    fence, AtomicBool, AtomicPtr, AtomicU32, AtomicU64, AtomicUsize, Ordering,
};
use std::sync::{mpsc, Arc, Condvar, Mutex};
use std::thread::{self, JoinHandle};
use std::time::{Duration, Instant};

// ============================================================================
// 1. Constants & Memory Layout Definitions
// ============================================================================

pub const CACHE_LINE_SIZE: usize = 64;
pub const DIRECT_IO_ALIGNMENT: usize = 4096;
pub const WAL_BUFFER_CAPACITY: usize = 2 * 1024 * 1024; // 2MB Ring Buffers
pub const GROUP_COMMIT_FLUSH_BYTES: usize = 64 * 1024; // 64KB Threshold
pub const GROUP_COMMIT_TIMEOUT_MICROS: u64 = 50; // 50µs Latency Bound

pub const SENTINEL_TX_ACTIVE: u64 = u64::MAX;
pub const FLAG_TOMBSTONE: u16 = 1 << 0;
pub const FLAG_INLINE: u16 = 1 << 1;

pub const WAL_MAGIC: u32 = 0x57414C31; // "WAL1"
pub const WAL_RECORD_TX_BEGIN: u8 = 1;
pub const WAL_RECORD_PUT: u8 = 2;
pub const WAL_RECORD_DELETE: u8 = 3;
pub const WAL_RECORD_TX_COMMIT: u8 = 4;

pub type TxId = u64;
pub type Lsn = u64;
pub type Key = u64;

// ============================================================================
// 2. Hardware-Aligned Memory Allocator for Direct I/O
// ============================================================================

pub struct AlignedBuffer {
    ptr: *mut u8,
    layout: Layout,
    capacity: usize,
}

unsafe impl Send for AlignedBuffer {}
unsafe impl Sync for AlignedBuffer {}

impl AlignedBuffer {
    pub fn new(capacity: usize, alignment: usize) -> Self {
        assert!(capacity > 0 && capacity % alignment == 0);
        let layout = Layout::from_size_align(capacity, alignment).expect("Invalid Layout");
        let ptr = unsafe { alloc_zeroed(layout) };
        if ptr.is_null() {
            std::alloc::handle_alloc_error(layout);
        }
        Self { ptr, layout, capacity }
    }

    #[inline(always)]
    pub fn as_ptr(&self) -> *const u8 {
        self.ptr
    }

    #[inline(always)]
    pub fn as_mut_ptr(&self) -> *mut u8 {
        self.ptr
    }

    #[inline(always)]
    pub fn capacity(&self) -> usize {
        self.capacity
    }

    #[inline(always)]
    pub fn as_slice(&self) -> &[u8] {
        unsafe { std::slice::from_raw_parts(self.ptr, self.capacity) }
    }

    #[inline(always)]
    pub fn as_mut_slice(&mut self) -> &mut [u8] {
        unsafe { std::slice::from_raw_parts_mut(self.ptr, self.capacity) }
    }
}

impl Drop for AlignedBuffer {
    fn drop(&mut self) {
        unsafe {
            dealloc(self.ptr, self.layout);
        }
    }
}

// ============================================================================
// 3. CRC32C Checksum Implementation (Hardware / Software Fallback)
// ============================================================================

pub fn crc32c(data: &[u8]) -> u32 {
    let mut crc = !0u32;
    for &byte in data {
        crc ^= byte as u32;
        for _ in 0..8 {
            crc = if crc & 1 != 0 {
                (crc >> 1) ^ 0x82F63B78
            } else {
                crc >> 1
            };
        }
    }
    !crc
}

