const MAX_THREADS: usize = 128;
const EPOCH_MASK: usize = 3;

/// Limbo bag holding pointers to retired versions.
struct LimboBag {
    nodes: Vec<*mut VersionRecord>,
}

impl LimboBag {
    fn new() -> Self {
        Self { nodes: Vec::with_capacity(1024) }
    }

    fn reclaim_all(&mut self) {
        for &ptr in &self.nodes {
            unsafe {
                VersionRecord::deallocate(ptr);
            }
        }
        self.nodes.clear();
    }
}

#[repr(C, align(64))]
pub struct ThreadSlot {
    pub active: AtomicBool,
    /// Epoch observed when entering a critical region (SENTINEL = quiescent)
    pub local_epoch: AtomicUsize,
}

impl ThreadSlot {
    const QUIESCENT: usize = usize::MAX;

    const fn new() -> Self {
        Self {
            active: AtomicBool::new(false),
            local_epoch: AtomicUsize::new(Self::QUIESCENT),
        }
    }
}

pub struct EpochManager {
    pub global_epoch: AtomicUsize,
    pub slots: Box<[ThreadSlot; MAX_THREADS]>,
    limbo: Mutex<[LimboBag; 3]>,
}

impl EpochManager {
    pub fn new() -> Self {
        const INIT_SLOT: ThreadSlot = ThreadSlot::new();
        let slots = Box::new([INIT_SLOT; MAX_THREADS]);

        Self {
            global_epoch: AtomicUsize::new(0),
            slots,
            limbo: Mutex::new([LimboBag::new(), LimboBag::new(), LimboBag::new()]),
        }
    }

    /// Register a thread to acquire a slot handle.
    pub fn register(&self) -> ThreadRegistration {
        for (i, slot) in self.slots.iter().enumerate() {
            if !slot.active.load(Ordering::Relaxed) {
                if slot
                    .active
                    .compare_exchange_weak(false, true, Ordering::Acquire, Ordering::Relaxed)
                    .is_ok()
                {
                    return ThreadRegistration {
                        slot_idx: i,
                        manager: self as *const Self,
                    };
                }
            }
        }
        panic!("Exceeded maximum thread capacity for EpochManager");
    }

    /// Advance global epoch and reclaim bags older than 2 epochs.
    pub fn try_advance_and_reclaim(&self) -> bool {
        let current = self.global_epoch.load(Ordering::Acquire);

        // Verify if all active threads have witnessed the current epoch.
        for slot in self.slots.iter() {
            if slot.active.load(Ordering::Acquire) {
                let local = slot.local_epoch.load(Ordering::Acquire);
                if local != ThreadSlot::QUIESCENT && local != current {
                    return false; // A reader is still in an older epoch
                }
            }
        }

        let next_epoch = current.wrapping_add(1);
        self.global_epoch.store(next_epoch, Ordering::Release);

        // Safe to reclaim (next_epoch + 1) % 3 bag
        let reclaim_idx = (current + 1) % EPOCH_MASK;
        if let Ok(mut bags) = self.limbo.try_lock() {
            bags[reclaim_idx].reclaim_all();
        }

        true
    }

    pub fn retire(&self, ptr: *mut VersionRecord) {
        let epoch = self.global_epoch.load(Ordering::Acquire);
        let bag_idx = epoch % EPOCH_MASK;
        let mut bags = self.limbo.lock().unwrap();
        bags[bag_idx].nodes.push(ptr);
    }
}

pub struct ThreadRegistration {
    slot_idx: usize,
    manager: *const EpochManager,
}

unsafe impl Send for ThreadRegistration {}

impl ThreadRegistration {
    #[inline(always)]
    pub fn enter(&self) -> EpochGuard {
        let mgr = unsafe { &*self.manager };
        let g_epoch = mgr.global_epoch.load(Ordering::Acquire);
        mgr.slots[self.slot_idx]
            .local_epoch
            .store(g_epoch, Ordering::Release);
        fence(Ordering::SeqCst); // Memory fence to guarantee local epoch visible before reading versions

        EpochGuard { registration: self }
    }

    #[inline(always)]
    pub fn exit(&self) {
        let mgr = unsafe { &*self.manager };
        mgr.slots[self.slot_idx]
            .local_epoch
            .store(ThreadSlot::QUIESCENT, Ordering::Release);
    }
}

impl Drop for ThreadRegistration {
    fn drop(&mut self) {
        let mgr = unsafe { &*self.manager };
        mgr.slots[self.slot_idx]
            .local_epoch
            .store(ThreadSlot::QUIESCENT, Ordering::Release);
        mgr.slots[self.slot_idx]
            .active
            .store(false, Ordering::Release);
    }
}

pub struct EpochGuard<'a> {
    registration: &'a ThreadRegistration,
}

impl<'a> Drop for EpochGuard<'a> {
    #[inline(always)]
    fn drop(&mut self) {
        self.registration.exit();
    }
}

