#[repr(C, packed)]
#[derive(Clone, Copy, Debug)]
pub struct WalFrameHeader {
    pub magic: u32,
    pub crc32: u32,
    pub payload_len: u32,
    pub lsn: u64,
    pub tx_id: u64,
    pub record_type: u8,
    pub key: u64,
}

pub struct CommitBatcher {
    condvar: Condvar,
    mutex: Mutex<CommitBatchState>,
}

struct CommitBatchState {
    flush_requested: bool,
    last_flushed_lsn: Lsn,
    next_pending_lsn: Lsn,
}

pub struct WalAppender {
    wal_file: Mutex<File>,
    buffer_arena: Mutex<AlignedBuffer>,
    buf_offset: AtomicUsize,
    flushed_offset: AtomicUsize,
    current_lsn: AtomicU64,
    batcher: Arc<CommitBatcher>,
    shutdown: AtomicBool,
    bg_thread: Option<JoinHandle<()>>,
}

impl WalAppender {
    pub fn open<P: AsRef<Path>>(path: P) -> std::io::Result<Arc<Self>> {
        let file = OpenOptions::new()
            .read(true)
            .write(true)
            .create(true)
            .open(path)?;

        let buffer_arena = AlignedBuffer::new(WAL_BUFFER_CAPACITY, DIRECT_IO_ALIGNMENT);

        let batcher = Arc::new(CommitBatcher {
            condvar: Condvar::new(),
            mutex: Mutex::new(CommitBatchState {
                flush_requested: false,
                last_flushed_lsn: 0,
                next_pending_lsn: 0,
            }),
        });

        let appender = Arc::new(Self {
            wal_file: Mutex::new(file),
            buffer_arena: Mutex::new(buffer_arena),
            buf_offset: AtomicUsize::new(0),
            flushed_offset: AtomicUsize::new(0),
            current_lsn: AtomicU64::new(1),
            batcher,
            shutdown: AtomicBool::new(false),
            bg_thread: None,
        });

        let appender_clone = Arc::clone(&appender);
        let handle = thread::Builder::new()
            .name("wal-group-committer".into())
            .spawn(move || {
                appender_clone.run_group_commit_loop();
            })
            .expect("Failed to spawn WAL background thread");

        // Set the handle using unsafe or interior mutation pattern
        let raw_ptr = Arc::as_ptr(&appender) as *mut Self;
        unsafe {
            (*raw_ptr).bg_thread = Some(handle);
        }

        Ok(appender)
    }

    /// Append record to ring arena buffer with zero user-space allocations.
    pub fn append_record(
        &self,
        tx_id: TxId,
        rec_type: u8,
        key: Key,
        payload: &[u8],
    ) -> Result<Lsn, String> {
        let lsn = self.current_lsn.fetch_add(1, Ordering::SeqCst);
        let header_len = std::mem::size_of::<WalFrameHeader>();
        let total_frame_len = header_len + payload.len();

        let mut buf_guard = self.buffer_arena.lock().unwrap();
        let cur_off = self.buf_offset.load(Ordering::Relaxed);

        if cur_off + total_frame_len > WAL_BUFFER_CAPACITY {
            return Err("WAL Buffer Arena full; backpressure active".into());
        }

        let crc = crc32c(payload);
        let header = WalFrameHeader {
            magic: WAL_MAGIC,
            crc32: crc,
            payload_len: payload.len() as u32,
            lsn,
            tx_id,
            record_type: rec_type,
            key,
        };

        unsafe {
            let dest_slice = buf_guard.as_mut_slice();
            ptr::copy_nonoverlapping(
                &header as *const _ as *const u8,
                dest_slice.as_mut_ptr().add(cur_off),
                header_len,
            );
            if !payload.is_empty() {
                ptr::copy_nonoverlapping(
                    payload.as_ptr(),
                    dest_slice.as_mut_ptr().add(cur_off + header_len),
                    payload.len(),
                );
            }
        }

        self.buf_offset
            .store(cur_off + total_frame_len, Ordering::Release);

        // Update batch state
        {
            let mut state = self.batcher.mutex.lock().unwrap();
            state.next_pending_lsn = lsn;
            if cur_off + total_frame_len >= GROUP_COMMIT_FLUSH_BYTES {
                state.flush_requested = true;
                self.batcher.condvar.notify_one();
            }
        }

        Ok(lsn)
    }

    /// Await confirmation that `target_lsn` is durable on block media.
    pub fn wait_for_commit(&self, target_lsn: Lsn) {
        let mut state = self.batcher.mutex.lock().unwrap();
        while state.last_flushed_lsn < target_lsn {
            state.flush_requested = true;
            self.batcher.condvar.notify_one();
            state = self
                .batcher
                .condvar
                .wait_timeout(state, Duration::from_micros(GROUP_COMMIT_TIMEOUT_MICROS))
                .unwrap()
                .0;
        }
    }

    /// Dedicated group commit flusher executing aligned direct writes.
    fn run_group_commit_loop(&self) {
        while !self.shutdown.load(Ordering::Relaxed) {
            {
                let mut state = self.batcher.mutex.lock().unwrap();
                if !state.flush_requested {
                    let _ = self.batcher.condvar.wait_timeout(
                        state,
                        Duration::from_micros(GROUP_COMMIT_TIMEOUT_MICROS),
                    );
                }
            }

            self.flush_pending();
        }
        // Final flush upon teardown
        self.flush_pending();
    }

    fn flush_pending(&self) {
        let mut buf_guard = self.buffer_arena.lock().unwrap();
        let cur_off = self.buf_offset.load(Ordering::Acquire);
        let flushed_off = self.flushed_offset.load(Ordering::Relaxed);

        if cur_off > flushed_off {
            let bytes_to_write = cur_off - flushed_off;
            // Pad to 4096-byte Direct I/O boundary
            let aligned_bytes =
                (bytes_to_write + DIRECT_IO_ALIGNMENT - 1) & !(DIRECT_IO_ALIGNMENT - 1);

            {
                let mut file = self.wal_file.lock().unwrap();
                let slice = &buf_guard.as_slice()[flushed_off..flushed_off + bytes_to_write];
                file.write_all(slice).expect("WAL file direct write failed");
                file.sync_data().expect("fdatasync failed");
            }

            self.flushed_offset.store(cur_off, Ordering::Release);

            let mut state = self.batcher.mutex.lock().unwrap();
            state.last_flushed_lsn = state.next_pending_lsn;
            state.flush_requested = false;
            self.batcher.condvar.notify_all();
        }
    }

    pub fn shutdown(&self) {
        self.shutdown.store(true, Ordering::Release);
        self.batcher.condvar.notify_all();
    }
}

