// 9. Crash Recovery & Validation Subsystem
// ============================================================================

#[derive(Debug)]
pub enum RecoveryError {
    Io(std::io::Error),
    CorruptHeader,
    CrcMismatch { expected: u32, calculated: u32 },
    TornWriteDetected { offset: u64 },
}

pub struct RecoveryManager;

impl RecoveryManager {
    pub fn recover<P: AsRef<Path>>(
        wal_path: P,
        index_capacity: usize,
    ) -> Result<(Arc<MvccIndex>, Lsn), RecoveryError> {
        let mut file = File::open(wal_path).map_err(RecoveryError::Io)?;
        let file_len = file.metadata().map_err(RecoveryError::Io)?.len();
        let index = Arc::new(MvccIndex::new(index_capacity));

        let mut offset = 0u64;
        let mut max_lsn = 0u64;
        let header_size = std::mem::size_of::<WalFrameHeader>() as u64;

        // Pending uncommitted transactions: tx_id -> Vec<(key, record_type, payload)>
        let mut uncommitted_txs: HashMap<TxId, Vec<(Key, u8, Vec<u8>)>> = HashMap::new();

        let mut header_buf = vec![0u8; header_size as usize];

        while offset + header_size <= file_len {
            file.seek(SeekFrom::Start(offset)).map_err(RecoveryError::Io)?;
            if let Err(_) = file.read_exact(&mut header_buf) {
                break; // Premature EOF
            }

            let header: WalFrameHeader =
                unsafe { ptr::read(header_buf.as_ptr() as *const WalFrameHeader) };

            if header.magic != WAL_MAGIC {
                // Detected torn block boundary or end of valid WAL entries
                return Err(RecoveryError::TornWriteDetected { offset });
            }

            let payload_size = header.payload_len as usize;
            let mut payload = vec![0u8; payload_size];
            if payload_size > 0 {
                file.seek(SeekFrom::Start(offset + header_size))
                    .map_err(RecoveryError::Io)?;
                if let Err(_) = file.read_exact(&mut payload) {
                    return Err(RecoveryError::TornWriteDetected { offset });
                }

                let calc_crc = crc32c(&payload);
                if calc_crc != header.crc32 {
                    return Err(RecoveryError::CrcMismatch {
                        expected: header.crc32,
                        calculated: calc_crc,
                    });
                }
            }

            if header.lsn > max_lsn {
                max_lsn = header.lsn;
            }

            // Reconstruct transaction state
            match header.record_type {
                WAL_RECORD_TX_BEGIN => {
                    uncommitted_txs.insert(header.tx_id, Vec::new());
                }
                WAL_RECORD_PUT | WAL_RECORD_DELETE => {
                    if let Some(ops) = uncommitted_txs.get_mut(&header.tx_id) {
                        ops.push((header.key, header.record_type, payload));
                    }
                }
                WAL_RECORD_TX_COMMIT => {
                    if let Some(ops) = uncommitted_txs.remove(&header.tx_id) {
                        for (key, rec_type, p_data) in ops {
                            let flags = if rec_type == WAL_RECORD_DELETE {
                                FLAG_TOMBSTONE
                            } else {
                                0
                            };
                            let head = index.get_head(key);
                            let new_node =
                                VersionRecord::allocate(header.tx_id, flags, &p_data, head);
                            if !head.is_null() {
                                unsafe {
                                    (*head)
                                        .tx_id_deleted
                                        .store(header.tx_id, Ordering::Relaxed);
                                }
                            }
                            index.cas_head(key, head, new_node);
                        }
                    }
                }
                _ => return Err(RecoveryError::CorruptHeader),
            }

            offset += header_size + payload_size as u64;
        }

        Ok((index, max_lsn))
    }
}

