// 0. HARDWARE CONSTANTS & CACHE ALIGNMENT
// ============================================================================
#if defined(__cpp_lib_hardware_interference_size)
    using std::hardware_destructive_interference_size;
#else
    constexpr size_t hardware_destructive_interference_size = 64;
#endif

constexpr size_t PAGE_SIZE_DIRECT_IO = 4096;
constexpr uint64_t TX_ID_ACTIVE = UINT64_MAX;
constexpr uint16_t FLAG_TOMBSTONE = 1 << 0;
constexpr uint16_t FLAG_INLINED   = 1 << 1;

// ============================================================================
// 1. FAST CRC32-C (SSE4.2 Hardware accelerated / Fallback)
// ============================================================================
namespace crc32c {
    inline uint32_t calculate(const uint8_t* data, size_t length, uint32_t crc = 0xFFFFFFFF) {
#if defined(__x86_64__) || defined(_M_X64)
        uint64_t crc64 = crc;
        while (length >= 8) {
            crc64 = __builtin_ia32_crc32di(crc64, *reinterpret_cast<const uint64_t*>(data));
            data += 8;
            length -= 8;
        }
        crc = static_cast<uint32_t>(crc64);
        if (length >= 4) {
            crc = __builtin_ia32_crc32si(crc, *reinterpret_cast<const uint32_t*>(data));
            data += 4;
            length -= 4;
        }
        if (length >= 2) {
            crc = __builtin_ia32_crc32hi(crc, *reinterpret_cast<const uint16_t*>(data));
            data += 2;
            length -= 2;
        }
        if (length >= 1) {
            crc = __builtin_ia32_crc32qi(crc, *data);
        }
        return crc ^ 0xFFFFFFFF;
#else
        // Fallback Bitwise CRC32C
        crc = ~crc;
        while (length--) {
            crc ^= *data++;
            for (int k = 0; k < 8; k++)
                crc = (crc >> 1) ^ (0x82F63B78 & (0 - (crc & 1)));
        }
        return ~crc;
#endif
    }
}

// ============================================================================
// 2. MVCC DATA STRUCTURES
// ============================================================================
struct alignas(hardware_destructive_interference_size) VersionRecord {
    uint64_t tx_id_created;
    std::atomic<uint64_t> tx_id_deleted;
    uint32_t value_len;
    uint16_t flags;
    uint16_t reserved;
    std::atomic<VersionRecord*> next;
    uint8_t payload[1]; // Flexible array payload

    static VersionRecord* allocate(uint64_t created, uint32_t len, uint16_t flags, const uint8_t* val) {
        size_t total_size = sizeof(VersionRecord) - 1 + len;
        void* raw_mem = ::operator new(total_size, std::align_val_t{alignof(VersionRecord)});
        auto* rec = new (raw_mem) VersionRecord();
        rec->tx_id_created = created;
        rec->tx_id_deleted.store(TX_ID_ACTIVE, std::memory_order_relaxed);
        rec->value_len = len;
        rec->flags = flags;
        rec->next.store(nullptr, std::memory_order_relaxed);
        if (len > 0 && val != nullptr) {
            std::memcpy(rec->payload, val, len);
        }
        return rec;
    }

    static void destroy(VersionRecord* ptr) {
        if (!ptr) return;
        ptr->~VersionRecord();
        ::operator delete(ptr, std::align_val_t{alignof(VersionRecord)});
    }
};

// ============================================================================
// 3. LOCK-FREE EPOCH-BASED RECLAMATION (EBR)
// ============================================================================
class EpochManager {
public:
    static constexpr size_t MAX_THREADS = 128;
    static constexpr uint64_t INACTIVE_EPOCH = UINT64_MAX;

    struct alignas(hardware_destructive_interference_size) ThreadRegistration {
        std::atomic<uint64_t> active_epoch{INACTIVE_EPOCH};
        std::atomic<bool> is_registered{false};
    };

    struct alignas(hardware_destructive_interference_size) RetiredNode {
        VersionRecord* record;
        RetiredNode* next;
    };

    EpochManager() : global_epoch_(0) {
        for (auto& slot : thread_slots_) {
            slot.is_registered.store(false, std::memory_order_relaxed);
            slot.active_epoch.store(INACTIVE_EPOCH, std::memory_order_relaxed);
        }
        for (size_t i = 0; i < 3; ++i) {
            retired_lists_[i].store(nullptr, std::memory_order_relaxed);
        }
    }

    ~EpochManager() {
        for (size_t i = 0; i < 3; ++i) {
            reclaim_list(retired_lists_[i].exchange(nullptr, std::memory_order_acquire));
        }
    }

    size_t register_thread() {
        for (size_t i = 0; i < MAX_THREADS; ++i) {
            bool expected = false;
            if (thread_slots_[i].is_registered.compare_exchange_strong(
                    expected, true, std::memory_order_acq_rel, std::memory_order_relaxed)) {
                return i;
            }
        }
        throw std::runtime_error("Exceeded maximum threads in EpochManager");
    }

    void unregister_thread(size_t slot) {
        thread_slots_[slot].active_epoch.store(INACTIVE_EPOCH, std::memory_order_release);
        thread_slots_[slot].is_registered.store(false, std::memory_order_release);
    }

    // Reader entering critical section
    void enter_critical(size_t slot) {
        // Read global epoch and announce intention with release ordering
        uint64_t current = global_epoch_.load(std::memory_order_relaxed);
        thread_slots_[slot].active_epoch.store(current, std::memory_order_release);
    }

    // Reader leaving critical section
    void exit_critical(size_t slot) {
        thread_slots_[slot].active_epoch.store(INACTIVE_EPOCH, std::memory_order_release);
    }

    // Enqueue an obsolete record for retirement
    void retire(VersionRecord* rec) {
        auto* node = new RetiredNode{rec, nullptr};
        uint64_t epoch = global_epoch_.load(std::memory_order_relaxed);
        size_t bucket = epoch % 3;

        // Push to retired list lock-free
        RetiredNode* head = retired_lists_[bucket].load(std::memory_order_relaxed);
        do {
            node->next = head;
        } while (!retired_lists_[bucket].compare_exchange_weak(
            head, node, std::memory_order_release, std::memory_order_relaxed));
    }

    // GC Sweep tries to advance the global epoch and free safe buckets
    void try_advance_and_sweep() {
        uint64_t current = global_epoch_.load(std::memory_order_acquire);

        // Check if all registered active threads have observed the current epoch
        for (size_t i = 0; i < MAX_THREADS; ++i) {
            if (thread_slots_[i].is_registered.load(std::memory_order_relaxed)) {
                uint64_t th_epoch = thread_slots_[i].active_epoch.load(std::memory_order_acquire);
                if (th_epoch != INACTIVE_EPOCH && th_epoch < current) {
                    // A thread is still lagging in an older epoch
                    return;
                }
            }
        }

        // Safe to advance global epoch
        if (global_epoch_.compare_exchange_strong(current, current + 1, std::memory_order_acq_rel)) {
            // Bucket (current + 2) % 3 is 2 epochs behind, meaning no readers can hold references
            size_t safe_bucket = (current + 2) % 3;
            RetiredNode* nodes = retired_lists_[safe_bucket].exchange(nullptr, std::memory_order_acq_rel);
            reclaim_list(nodes);
        }
    }

    uint64_t get_min_active_snapshot() const {
        uint64_t min_snapshot = global_epoch_.load(std::memory_order_acquire);
        for (size_t i = 0; i < MAX_THREADS; ++i) {
            if (thread_slots_[i].is_registered.load(std::memory_order_relaxed)) {
                uint64_t th_epoch = thread_slots_[i].active_epoch.load(std::memory_order_acquire);
                if (th_epoch != INACTIVE_EPOCH && th_epoch < min_snapshot) {
                    min_snapshot = th_epoch;
                }
            }
        }
        return min_snapshot;
    }

private:
    void reclaim_list(RetiredNode* head) {
        while (head != nullptr) {
            RetiredNode* next = head->next;
            VersionRecord::destroy(head->record);
            delete head;
            head = next;
        }
    }

    alignas(hardware_destructive_interference_size) std::atomic<uint64_t> global_epoch_;
    alignas(hardware_destructive_interference_size) std::array<ThreadRegistration, MAX_THREADS> thread_slots_;
    alignas(hardware_destructive_interference_size) std::array<std::atomic<RetiredNode*>, 3> retired_lists_;
};

// ============================================================================
// 4. LOCK-FREE MVCC INDEX
// ============================================================================
class MvccIndex {
public:
    static constexpr size_t NUM_BUCKETS = 65536;

    struct Bucket {
        alignas(hardware_destructive_interference_size) std::atomic<VersionRecord*> head{nullptr};
    };

    MvccIndex() = default;

    ~MvccIndex() {
        for (auto& bucket : buckets_) {
            VersionRecord* cur = bucket.head.exchange(nullptr, std::memory_order_relaxed);
            while (cur) {
                VersionRecord* next = cur->next.load(std::memory_order_relaxed);
                VersionRecord::destroy(cur);
                cur = next;
            }
        }
    }

    // Point Read: Wait-Free snapshot traversal
    // Invariant: Memory ordering of head & next load is ACQUIRE to guarantee publication safety.
    bool read(uint64_t key, uint64_t snapshot_ts, std::vector<uint8_t>& out_val) {
        size_t bucket_idx = hash(key) % NUM_BUCKETS;
        VersionRecord* curr = buckets_[bucket_idx].head.load(std::memory_order_acquire);

        while (curr != nullptr) {
            uint64_t created = curr->tx_id_created;
            uint64_t deleted = curr->tx_id_deleted.load(std::memory_order_acquire);

            // Snapshot visibility rules:
            // Visible if: created <= snapshot_ts AND (deleted == ACTIVE OR deleted > snapshot_ts)
            if (created <= snapshot_ts && (deleted > snapshot_ts)) {
                if (curr->flags & FLAG_TOMBSTONE) {
                    return false; // Key deleted as of snapshot
                }
                out_val.resize(curr->value_len);
                std::memcpy(out_val.data(), curr->payload, curr->value_len);
                return true;
            }
            curr = curr->next.load(std::memory_order_acquire);
        }
        return false;
    }

    // Atomic insert of a new version. Returns previous version for update bookkeeping.
    bool insert_version(uint64_t key, VersionRecord* new_rec, VersionRecord*& prev_out) {
        size_t bucket_idx = hash(key) % NUM_BUCKETS;
        VersionRecord* head = buckets_[bucket_idx].head.load(std::memory_order_relaxed);
        do {
            new_rec->next.store(head, std::memory_order_relaxed);
            // RELEASE CAS ensures that the initialization of new_rec is visible before it becomes head
        } while (!buckets_[bucket_idx].head.compare_exchange_weak(
            head, new_rec, std::memory_order_release, std::memory_order_relaxed));

        prev_out = head;
        return true;
    }

    // Prune stale records older than watermark
    void gc_chain(uint64_t key, uint64_t min_active_ts, EpochManager& ebr) {
        size_t bucket_idx = hash(key) % NUM_BUCKETS;
        VersionRecord* curr = buckets_[bucket_idx].head.load(std::memory_order_acquire);
        if (!curr) return;

        // Traverse down the chain. Find versions unlinked or strictly shadowed beneath watermark
        VersionRecord* prev = curr;
        curr = curr->next.load(std::memory_order_acquire);

        while (curr != nullptr) {
            uint64_t deleted = curr->tx_id_deleted.load(std::memory_order_acquire);
            if (deleted <= min_active_ts) {
                // This version and everything beneath it are dead for all active and future snapshots
                VersionRecord* to_prune = curr;
                // Atomic unlink
                prev->next.store(nullptr, std::memory_order_release);
                // Retire unlinked subtree to EBR
                while (to_prune != nullptr) {
                    VersionRecord* nxt = to_prune->next.load(std::memory_order_relaxed);
                    ebr.retire(to_prune);
                    to_prune = nxt;
                }
                break;
            }
            prev = curr;
            curr = curr->next.load(std::memory_order_acquire);
        }
    }

private:
    static inline size_t hash(uint64_t x) {
        x ^= x >> 30;
        x *= UINT64_C(0xbf58476d1ce4e5b9);
        x ^= x >> 27;
        x *= UINT64_C(0x94d049bb133111eb);
        x ^= x >> 31;
        return static_cast<size_t>(x);
    }

    std::array<Bucket, NUM_BUCKETS> buckets_;
};

// ============================================================================
// 5. DIRECT I/O ASYNCHRONOUS WAL PIPELINE
// ============================================================================
#pragma pack(push, 1)
struct WalHeader {
    uint32_t crc32c;
    uint32_t payload_len;
    uint64_t lsn;
    uint64_t tx_id;
    uint64_t key;
    uint16_t record_type; // 0: Put, 1: Delete
};
#pragma pack(pop)

class WalRingBuffer {
public:
    static constexpr size_t BUFFER_SIZE = 2 * 1024 * 1024; // 2MB Direct I/O Arena
    static constexpr size_t FLUSH_THRESHOLD_BYTES = 64 * 1024; // 64KB Group Commit Batch

    WalRingBuffer(const std::string& path) : file_path_(path), stop_flusher_(false), global_lsn_(1) {
        // Open file with O_DIRECT | O_CREAT | O_RDWR
        fd_ = ::open(path.c_str(), O_DIRECT | O_CREAT | O_RDWR | O_TRUNC, 0644);
        if (fd_ < 0) {
            // Fallback for filesystems lacking direct I/O support in dev/test mock
            fd_ = ::open(path.c_str(), O_CREAT | O_RDWR | O_TRUNC, 0644);
        }

        // Allocate aligned double buffers
        write_buf_ = static_cast<uint8_t*>(::aligned_alloc(PAGE_SIZE_DIRECT_IO, BUFFER_SIZE));
        flush_buf_ = static_cast<uint8_t*>(::aligned_alloc(PAGE_SIZE_DIRECT_IO, BUFFER_SIZE));

        buf_offset_.store(0, std::memory_order_relaxed);
        committed_lsn_.store(0, std::memory_order_release);

        flusher_thread_ = std::thread(&WalRingBuffer::flusher_loop, this);
    }

    ~WalRingBuffer() {
        stop_flusher_.store(true, std::memory_order_release);
        if (flusher_thread_.joinable()) flusher_thread_.join();

        if (fd_ >= 0) {
            ::close(fd_);
        }
        ::free(write_buf_);
        ::free(flush_buf_);
    }

    struct CommitRequest {
        uint64_t lsn;
        std::promise<uint64_t> promise;
    };

    std::future<uint64_t> append_record(uint64_t tx_id, uint64_t key, uint16_t type, std::span<const uint8_t> payload) {
        size_t total_len = sizeof(WalHeader) + payload.size();
        uint64_t lsn = global_lsn_.fetch_add(1, std::memory_order_acq_rel);

        // Atomic space reservation in write buffer
        size_t offset = buf_offset_.fetch_add(total_len, std::memory_order_acq_rel);
        if (offset + total_len > BUFFER_SIZE) {
            throw std::runtime_error("WAL Ring Buffer saturated: batch size overflow");
        }

        WalHeader header;
        header.payload_len = static_cast<uint32_t>(payload.size());
        header.lsn = lsn;
        header.tx_id = tx_id;
        header.key = key;
        header.record_type = type;

        // Compute checksum over metadata + payload
        uint32_t crc = crc32c::calculate(reinterpret_cast<const uint8_t*>(&header) + 4, sizeof(WalHeader) - 4);
        if (!payload.empty()) {
            crc = crc32c::calculate(payload.data(), payload.size(), crc ^ 0xFFFFFFFF);
        }
        header.crc32c = crc;

        // Write directly to user-space DMA staging buffer
        std::memcpy(write_buf_ + offset, &header, sizeof(WalHeader));
        if (!payload.empty()) {
            std::memcpy(write_buf_ + offset + sizeof(WalHeader), payload.data(), payload.size());
        }

        // Register commit promise
        auto req = std::make_shared<CommitRequest>();
        req->lsn = lsn;
        auto fut = req->promise.get_future();

        {
            std::lock_guard<std::mutex> lock(pending_mutex_);
            pending_requests_.push_back(req);
        }

        return fut;
    }

private:
    void flusher_loop() {
        size_t file_offset = 0;

        while (!stop_flusher_.load(std::memory_order_acquire)) {
            std::this_thread::sleep_for(std::chrono::microseconds(50)); // 50us group commit timer

            size_t bytes_to_write = buf_offset_.load(std::memory_order_acquire);
            if (bytes_to_write == 0) continue;

            // Reset write buffer offset atomically and swap buffers
            buf_offset_.store(0, std::memory_order_release);
            std::memcpy(flush_buf_, write_buf_, bytes_to_write);

            // Align bytes for Direct I/O to next PAGE_SIZE_DIRECT_IO boundary
            size_t aligned_bytes = (bytes_to_write + PAGE_SIZE_DIRECT_IO - 1) & ~(PAGE_SIZE_DIRECT_IO - 1);
            if (aligned_bytes > bytes_to_write) {
                // Zero out slack memory to prevent undefined disk state
                std::memset(flush_buf_ + bytes_to_write, 0, aligned_bytes - bytes_to_write);
            }

            // Direct I/O Asynchronous Submission simulation via low-overhead POSIX/Kernel pipeline
            ssize_t written = ::pwrite(fd_, flush_buf_, aligned_bytes, file_offset);
            if (written > 0) {
                file_offset += written;
            }

            // Group completion wakeups
            std::vector<std::shared_ptr<CommitRequest>> to_notify;
            {
                std::lock_guard<std::mutex> lock(pending_mutex_);
                to_notify.swap(pending_requests_);
            }

            uint64_t max_lsn = 0;
            for (auto& req : to_notify) {
                max_lsn = std::max(max_lsn, req->lsn);
                req->promise.set_value(req->lsn);
            }
            committed_lsn_.store(max_lsn, std::memory_order_release);
        }
    }

    std::string file_path_;
    int fd_;
    std::atomic<bool> stop_flusher_;
    std::atomic<uint64_t> global_lsn_;
    std::atomic<size_t> buf_offset_;
    std::atomic<uint64_t> committed_lsn_;

    uint8_t* write_buf_;
    uint8_t* flush_buf_;

    std::thread flusher_thread_;
    std::mutex pending_mutex_;
    std::vector<std::shared_ptr<CommitRequest>> pending_requests_;
};

// ============================================================================
// 6. STORAGE ENGINE ORCHESTRATOR
// ============================================================================
class StorageEngine {
public:
    enum class IsolationLevel {
        SnapshotIsolation
    };

    struct TxContext {
        uint64_t read_ts;
        uint64_t commit_ts;
        size_t ebr_slot;
        bool is_active;
    };

    StorageEngine(const std::string& wal_path) 
        : wal_(wal_path), next_tx_id_(1) {}

    TxContext begin_transaction(IsolationLevel /*level*/ = IsolationLevel::SnapshotIsolation) {
        size_t slot = ebr_.register_thread();
        ebr_.enter_critical(slot);
        uint64_t snapshot_ts = next_tx_id_.load(std::memory_order_acquire);
        return TxContext{snapshot_ts, 0, slot, true};
    }

    std::optional<std::vector<uint8_t>> read(TxContext& ctx, uint64_t key) {
        assert(ctx.is_active);
        std::vector<uint8_t> val;
        if (index_.read(key, ctx.read_ts, val)) {
            return val;
        }
        return std::nullopt;
    }

    void write(TxContext& ctx, uint64_t key, std::span<const uint8_t> value) {
        assert(ctx.is_active);
        if (ctx.commit_ts == 0) {
            ctx.commit_ts = next_tx_id_.fetch_add(1, std::memory_order_acq_rel);
        }

        // Allocate VersionRecord
        VersionRecord* rec = VersionRecord::allocate(ctx.commit_ts, static_cast<uint32_t>(value.size()), 0, value.data());

        // Lock-Free MVCC Chain Insertion
        VersionRecord* prev_version = nullptr;
        index_.insert_version(key, rec, prev_version);

        // Mark previous version obsolete as of ctx.commit_ts
        if (prev_version != nullptr) {
            prev_version->tx_id_deleted.store(ctx.commit_ts, std::memory_order_release);
        }

        // Write to WAL pipeline
        wal_future_ = wal_.append_record(ctx.commit_ts, key, 0, value);
    }

    std::future<uint64_t> commit(TxContext& ctx) {
        assert(ctx.is_active);
        ebr_.exit_critical(ctx.ebr_slot);
        ebr_.unregister_thread(ctx.ebr_slot);
        ctx.is_active = false;

        if (wal_future_.valid()) {
            return std::move(wal_future_);
        }
        std::promise<uint64_t> p;
        p.set_value(0);
        return p.get_future();
    }

    void gc_sweep() {
        ebr_.try_advance_and_sweep();
    }

    void gc_key(uint64_t key) {
        uint64_t min_snapshot = ebr_.get_min_active_snapshot();
        index_.gc_chain(key, min_snapshot, ebr_);
    }

    // Crash Recovery Engine
    static MvccIndex* recover(const std::string& wal_path, uint64_t& max_tx_recovered) {
        int fd = ::open(wal_path.c_str(), O_RDONLY);
        if (fd < 0) throw std::runtime_error("Failed to open WAL for recovery");

        struct stat st;
        ::fstat(fd, &st);
        size_t fsize = st.st_size;
        if (fsize == 0) {
            ::close(fd);
            return new MvccIndex();
        }

        std::vector<uint8_t> buffer(fsize);
        ssize_t read_bytes = ::pread(fd, buffer.data(), fsize, 0);
        ::close(fd);

        auto* recovered_index = new MvccIndex();
        size_t offset = 0;
        max_tx_recovered = 0;

        while (offset + sizeof(WalHeader) <= static_cast<size_t>(read_bytes)) {
            const auto* hdr = reinterpret_cast<const WalHeader*>(buffer.data() + offset);

            // Check for zeroed trailing padding (Direct I/O 4KB block alignment artifact)
            if (hdr->lsn == 0 && hdr->tx_id == 0) break;

            if (offset + sizeof(WalHeader) + hdr->payload_len > static_cast<size_t>(read_bytes)) {
                // Torn write detected at log boundary: halt recovery at clean state
                break;
            }

            // Verify integrity
            uint32_t expected_crc = hdr->crc32c;
            uint32_t computed_crc = crc32c::calculate(
                reinterpret_cast<const uint8_t*>(hdr) + 4, sizeof(WalHeader) - 4);
            if (hdr->payload_len > 0) {
                computed_crc = crc32c::calculate(
                    buffer.data() + offset + sizeof(WalHeader), hdr->payload_len, computed_crc ^ 0xFFFFFFFF);
            }

            if (expected_crc != computed_crc) {
                // Checksum mismatch -> Torn record, end recovery safely
                break;
            }

            // Reconstruct in-memory version
            VersionRecord* rec = VersionRecord::allocate(
                hdr->tx_id, hdr->payload_len, 
                hdr->record_type == 1 ? FLAG_TOMBSTONE : 0, 
                buffer.data() + offset + sizeof(WalHeader));

            VersionRecord* prev = nullptr;
            recovered_index->insert_version(hdr->key, rec, prev);
            if (prev) {
                prev->tx_id_deleted.store(hdr->tx_id, std::memory_order_release);
            }

            max_tx_recovered = std::max(max_tx_recovered, hdr->tx_id);
            offset += sizeof(WalHeader) + hdr->payload_len;
        }

        return recovered_index;
    }

private:
    EpochManager ebr_;
    MvccIndex index_;
    WalRingBuffer wal_;
    alignas(hardware_destructive_interference_size) std::atomic<uint64_t> next_tx_id_;
    thread_local static std::future<uint64_t> wal_future_;
};

thread_local std::future<uint64_t> StorageEngine::wal_future_;

// ============================================================================
// 7. MULTI-THREADED STRESS BENCHMARK & TEST HARNESS
// ============================================================================
int main() {
    const std::string wal_path = "/tmp/mvcc_storage_engine.wal";
    std::cout << ">>> Initializing Lock-Free MVCC Storage Engine..." << std::endl;

    {
        StorageEngine engine(wal_path);
        constexpr int NUM_WRITERS = 4;
        constexpr int NUM_READERS = 4;
        constexpr int OPS_PER_THREAD = 10000;
        std::atomic<bool> start_signal{false};
        std::atomic<bool> stop_readers{false};

        // Snapshot Readers
        std::vector<std::thread> readers;
        std::atomic<uint64_t> successful_reads{0};

        for (int r = 0; r < NUM_READERS; ++r) {
            readers.emplace_back([&, r]() {
                while (!start_signal.load(std::memory_order_acquire)) {}
                while (!stop_readers.load(std::memory_order_relaxed)) {
                    auto ctx = engine.begin_transaction();
                    uint64_t key = rand() % 1000;
                    auto val = engine.read(ctx, key);
                    if (val.has_value()) {
                        successful_reads.fetch_add(1, std::memory_order_relaxed);
                    }
                    engine.commit(ctx);
                }
            });
        }

        // Concurrent Writers
        std::vector<std::thread> writers;
        for (int w = 0; w < NUM_WRITERS; ++w) {
            writers.emplace_back([&, w]() {
                while (!start_signal.load(std::memory_order_acquire)) {}
                for (int i = 0; i < OPS_PER_THREAD; ++i) {
                    auto ctx = engine.begin_transaction();
                    uint64_t key = i % 1000;
                    uint64_t val_data = (static_cast<uint64_t>(w) << 32) | i;
                    std::span<const uint8_t> payload(reinterpret_cast<const uint8_t*>(&val_data), sizeof(val_data));

                    engine.write(ctx, key, payload);
                    auto commit_fut = engine.commit(ctx);
                    commit_fut.get(); // Await asynchronous group commit

                    if (i % 200 == 0) {
                        engine.gc_key(key);
                        engine.gc_sweep();
                    }
                }
            });
        }

        auto start_time = std::chrono::high_resolution_clock::now();
        start_signal.store(true, std::memory_order_release);

        for (auto& t : writers) t.join();
        stop_readers.store(true, std::memory_order_release);
        for (auto& t : readers) t.join();

        auto end_time = std::chrono::high_resolution_clock::now();
        auto duration = std::chrono::duration_cast<std::chrono::milliseconds>(end_time - start_time).count();

        std::cout << ">>> Write Workload Completed: " << (NUM_WRITERS * OPS_PER_THREAD) 
                  << " writes in " << duration << " ms ("
                  << (double(NUM_WRITERS * OPS_PER_THREAD) / (duration / 1000.0)) << " IOPS)" << std::endl;
        std::cout << ">>> Concurrent Snapshot Reads Handled: " << successful_reads.load() << std::endl;
    }

    // Crash Recovery Simulation
    std::cout << ">>> Simulating Crash & Executing Log Recovery..." << std::endl;
    uint64_t max_recovered_tx = 0;
    std::unique_ptr<MvccIndex> recovered_index(StorageEngine::recover(wal_path, max_recovered_tx));

    std::cout << ">>> Recovery Succeeded. Max Recovered Transaction LSN/ID: " << max_recovered_tx << std::endl;

    // Validate state integrity in recovered index
    std::vector<uint8_t> out;
    bool found = recovered_index->read(0, max_recovered_tx, out);
    if (found && out.size() == sizeof(uint64_t)) {
        uint64_t val;
        std::memcpy(&val, out.data(), sizeof(uint64_t));
        std::cout << ">>> State Integrity Verified: Key 0 resolved to valid Tx Payload: " << val << std::endl;
    }

    ::unlink(wal_path.c_str());
    return 0;
}
